function demoSeed(){const t=localToday(),w=monday(t),m=w.slice(0,7),mk=(id,n)=>Array.from({length:n},(_,i)=>({id:`demo-${id}-${i}`,profileId:id,day:addDays(w,i),week:w,kind:['push','pull','legs'][i%3],note:'Sample workout',status:'approved',createdAt:ts()-i*9000,hasProof:false}));return {today:t,auth:null,profiles:[{id:'you',name:'Your profile',avatar:'',claimed:true,isAdmin:true,pin:'1234'},{id:'alex',name:'Alex',avatar:'',claimed:true,isAdmin:false,pin:'1234'},{id:'priya',name:'Priya',avatar:'',claimed:true,isAdmin:false,pin:'1234'},{id:'sam',name:'Sam',avatar:'',claimed:true,isAdmin:false,pin:'1234'}],checkins:[...mk('alex',4),...mk('priya',3),...mk('sam',2)],rules:[],defaults:fallback,done:[],cycleRules:[],proposals:[],proposalVotes:[],mvpVotes:[],mvpCrown:null,proofs:{},reactions:[],wallpapers:{}}}
let D=null;function saveD(){try{localStorage.setItem(previewKey,JSON.stringify(D))}catch{/* Some file:// browsers disallow local storage; demo remains in-memory */}};function initD(){try{D=JSON.parse(localStorage.getItem(previewKey))||demoSeed()}catch{D=demoSeed()}D.today=localToday();D.cycleRules ||= [];D.reactions ||= [];D.wallpapers ||= {};D.mvpCrown ||= null;D.jukebox ||= {url:'',title:'',selectedBy:null,updatedAt:0};D.radioHistory ||= [];saveD()}
function demoReq(url,method,b){if(!D)initD();const clone=()=>JSON.parse(JSON.stringify(D));const prof=id=>D.profiles.find(p=>p.id===id);if(url==='/api/bootstrap')return {setupRequired:false,profiles:D.profiles.map(({pin,...p})=>p),me:prof(D.auth)?((({pin,...p})=>p)(prof(D.auth))):null,today:D.today};if(url==='/api/login'){const p=prof(b.profileId);if(!p||p.pin!==b.pin)throw Error('Incorrect demo PIN (try 1234)');D.auth=p.id;saveD();return{ok:true}}if(url==='/api/claim'){const p=prof(b.profileId);if(!p||p.code!==b.claimCode)throw Error('Invalid invitation code');p.pin=b.pin;p.claimed=true;D.auth=p.id;saveD();return{ok:true}}if(url==='/api/logout'){D.auth=null;saveD();return{ok:true}}if(!D.auth)throw Error('Choose a profile');if(method==='DELETE'&&/^\/api\/messages\/[a-f0-9-]+$/.test(url)){const id=url.split('/').pop(),m=(D.messages||[]).find(x=>x.id===id);if(!m)throw Error('Message not found');if(m.profileId!==D.auth)throw Error('You can only delete your own posts');const ids=new Set([id]);(D.messages||[]).filter(x=>x.parentId===id).forEach(x=>ids.add(x.id));D.messages=D.messages.filter(x=>!ids.has(x.id));D.messageReactions=(D.messageReactions||[]).filter(x=>!ids.has(x.messageId));saveD();return{ok:true}}if(url==='/api/state'){const a=clone(),m=prof(D.auth);a.me=(({pin,...p})=>p)(m);a.profiles=a.profiles.map(({pin,code,...p})=>p);a.wallpaper=D.wallpapers[D.auth]||{theme:'ember',dim:.18,photo:''};a.jukebox=D.jukebox;a.feed=D.checkins.filter(c=>c.shareToFeed&&c.status==='approved'&&c.hasProof).map(c=>({id:c.id,profileId:c.profileId,kind:c.kind,day:c.day,note:c.note,createdAt:c.createdAt,myReaction:D.reactions.find(r=>r.checkinId===c.id&&r.profileId===D.auth)?.emoji||'',reactions:['🔥','👏','💪','❤️','🏆'].map(emoji=>({emoji,count:D.reactions.filter(r=>r.checkinId===c.id&&r.emoji===emoji).length}))}));return a}if(url==='/api/admin/mvp/crown'&&method==='POST'){if(!prof(b.profileId))throw Error('Unknown member');D.mvpCrown={profileId:b.profileId,source:'admin',awardedAt:ts()};saveD();return{ok:true,mvpCrown:D.mvpCrown}}if(url==='/api/admin/mvp/finalize'&&method==='POST'){const vs=D.mvpVotes.filter(v=>v.start===b.start),t={};vs.forEach(v=>t[v.candidateId]=(t[v.candidateId]||0)+1);const sorted=Object.entries(t).sort((a,b)=>b[1]-a[1]);if(!sorted.length||sorted[1]?.[1]===sorted[0][1])throw Error('No unique MVP winner');D.mvpCrown={profileId:sorted[0][0],source:'vote',cycleStart:b.start,awardedAt:ts()};saveD();return{ok:true,mvpCrown:D.mvpCrown}}if(url==='/api/jukebox'&&method==='POST'){const song={id:'00000000-0000-4000-8000-'+String(ts()).padStart(12,'0').slice(-12),url:b.url,title:b.title||'SoundCloud track',selectedBy:D.auth,updatedAt:ts()};D.jukebox={url:song.url,title:song.title,selectedBy:song.selectedBy,updatedAt:song.updatedAt};D.radioHistory.unshift(song);saveD();return{ok:true,jukebox:D.jukebox,radioHistory:D.radioHistory}}const selected=url.match(/^\/api\/radio-history\/([a-f0-9-]+)\/select$/);if(selected&&method==='POST'){const song=D.radioHistory.find(x=>x.id===selected[1]);if(!song)throw Error('Track not found');D.jukebox={url:song.url,title:song.title,selectedBy:song.selectedBy,updatedAt:ts()};saveD();return{ok:true,jukebox:D.jukebox,radioHistory:D.radioHistory}}const removedRadio=url.match(/^\/api\/radio-history\/([a-f0-9-]+)$/);if(removedRadio&&method==='DELETE'){const song=D.radioHistory.find(x=>x.id===removedRadio[1]);if(!song)throw Error('Track not found');if(song.selectedBy!==D.auth)throw Error('Only the contributor can remove this track');D.radioHistory=D.radioHistory.filter(x=>x.id!==song.id);if(D.jukebox?.url===song.url&&!D.radioHistory.some(x=>x.url===song.url)){D.jukebox={url:'',title:'',selectedBy:null,updatedAt:ts()}}saveD();return{ok:true,jukebox:D.jukebox,radioHistory:D.radioHistory}}const removed=url.match(/^\/api\/admin\/checkins\/(.*?)\/delete$/);if(removed&&method==='POST'){const c=D.checkins.find(x=>x.id===removed[1]);if(!c||c.status!=='approved')throw Error('Only approved sessions can be removed');c.status='deleted';c.shareToFeed=false;saveD();return{ok:true}}if(url==='/api/me/wallpaper'&&method==='PATCH'){D.wallpapers[D.auth]=b;saveD();return{ok:true}}if(url==='/api/admin/checkins'&&method==='POST'){if(D.checkins.filter(c=>c.profileId===b.profileId&&c.day===b.day&&c.status!=='deleted').length>=20)throw Error('Daily safety limit reached');D.checkins.unshift({id:'manual-'+ts(),profileId:b.profileId,day:b.day,week:monday(b.day),kind:b.kind,note:b.note||'',status:'approved',createdAt:ts(),hasProof:false,adminAdded:true,shareToFeed:false});saveD();return{ok:true}}const vis=url.match(/^\/api\/checkins\/(.*?)\/visibility$/);if(vis){const c=D.checkins.find(x=>x.id===vis[1]);if(!c||c.profileId!==D.auth)throw Error('Not your session');c.shareToFeed=b.visible;saveD();return{ok:true}}const react=url.match(/^\/api\/feed\/(.*?)\/react$/);if(react){const c=D.checkins.find(x=>x.id===react[1]);if(!c?.shareToFeed)throw Error('Not published');const old=D.reactions.find(r=>r.checkinId===c.id&&r.profileId===D.auth);D.reactions=D.reactions.filter(r=>!(r.checkinId===c.id&&r.profileId===D.auth));if(old?.emoji!==b.emoji)D.reactions.push({checkinId:c.id,profileId:D.auth,emoji:b.emoji});saveD();return{ok:true}}if(url==='/api/checkins'&&method==='POST'){if(D.checkins.filter(c=>c.profileId===D.auth&&c.day===D.today&&c.status!=='deleted').length>=20)throw Error('Daily safety limit reached');D.checkins.unshift({id:'demo-'+ts(),profileId:D.auth,day:D.today,week:monday(D.today),kind:b.kind,note:b.note,status:'pending',createdAt:ts(),hasProof:true,shareToFeed:b.shareToFeed===true});D.proofs[D.checkins[0].id]=b.proof;saveD();return{ok:true}}const proof=url.match(/^\/api\/checkins\/(.*?)\/proof$/);if(proof)return{proof:D.proofs[proof[1]]||''};const review=url.match(/^\/api\/checkins\/(.*?)\/review$/);if(review){const c=D.checkins.find(x=>x.id===review[1]);if(c)c.status=b.status}if(url==='/api/profiles'&&method==='POST'){const id='p'+ts(),code=Math.random().toString(36).slice(2,10).toUpperCase();D.profiles.push({id,name:b.name,avatar:b.avatar||'',claimed:false,isAdmin:false,pin:'',code});saveD();return{ok:true,inviteCode:code,profileId:id}}const edit=url.match(/^\/api\/profiles\/(.*?)$/);if(edit&&method==='PATCH'){const p=prof(edit[1]);p.name=b.name||p.name;if(b.avatar!==undefined)p.avatar=b.avatar}const reset=url.match(/^\/api\/profiles\/(.*?)\/reset$/);if(reset&&method==='POST'){const p=prof(reset[1]);p.pin='';p.claimed=false;p.code=Math.random().toString(36).slice(2,10).toUpperCase();saveD();return{inviteCode:p.code}}if(url==='/api/cycle-rules'&&method==='POST'){D.cycleRules=(D.cycleRules||[]).filter(r=>r.start!==b.start).concat(b)}if(url==='/api/rules'&&method==='POST'){D.rules=D.rules.filter(r=>r.month!==b.month).concat(b)}if(url==='/api/forfeit-completed'&&method==='POST'){const x=D.done.find(z=>z.profileId===b.profileId&&z.week===b.week);if(x)x.completed=x.completed?0:1;else D.done.push({month:b.week.slice(0,7),week:b.week,profileId:b.profileId,completed:1})}if(url==='/api/proposals'&&method==='POST'){D.proposals.push({id:'prop'+ts(),profileId:D.auth,createdAt:ts(),...b})}if(url==='/api/proposal-votes'&&method==='POST'){D.proposalVotes=D.proposalVotes.filter(x=>x.start!==addDays(cycleStart(D.today),28)||x.voterId!==D.auth);D.proposalVotes.push({start:addDays(cycleStart(D.today),28),voterId:D.auth,proposalId:b.proposalId})}if(url==='/api/apply-proposal'&&method==='POST'){const p=D.proposals.find(x=>x.id===b.proposalId);D.cycleRules=D.cycleRules.filter(x=>x.start!==p.start).concat({start:p.start,target:4,forfeits:p.forfeits})}if(url==='/api/mvp-votes'&&method==='POST'){if(D.mvpVotes.some(x=>x.start===b.start&&x.voterId===D.auth))throw Error('You have already voted');D.mvpVotes.push({start:b.start,voterId:D.auth,candidateId:b.candidateId,createdAt:ts()})}saveD();return{ok:true}}
async function api(url,method='GET',body){if(demoMode)return demoReq(url,method,body);const response=await fetch(url,{method,credentials:'same-origin',headers:method==='GET'?{}:{'content-type':'application/json'},body:method==='GET'?undefined:JSON.stringify(body||{})});let result;try{result=await response.json()}catch{throw Error(`Server returned ${response.status}`)}if(!response.ok)throw Error(result.error||'Request failed');return result}
let toastTimer;function toast(v){const e=q('#toast');e.textContent=v;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),3000)}
function setWallpaper(){let t={theme:'ember',dim:.18,photo:'',textColor:'default'};try{t={...t,...(S?.wallpaper||JSON.parse(localStorage.getItem('gymclo_wallpaper')||'{}'))}}catch{}const b=q('#wallpaper');b.className=t.photo?'':t.theme;b.style.backgroundImage=t.photo?`url(${JSON.stringify(t.photo)})`:'';document.documentElement.style.setProperty('--shade',t.dim);const shades={default:'#f6f3f5',rose:'#ffd5da',ice:'#d8edff',mint:'#d7ffe7',gold:'#ffe7bb',lavender:'#e7d6ff',warm:'#fff3e7'};document.documentElement.style.setProperty('--ink',shades[t.textColor]||shades.default);return t}
async function saveWallpaper(update){const t={...setWallpaper(),...update};if(S&&!demoMode){await api('/api/me/wallpaper','PATCH',t);S.wallpaper=t}else{try{localStorage.setItem('gymclo_wallpaper',JSON.stringify(t))}catch{throw Error('Wallpaper too large for browser storage')}if(S)S.wallpaper=t}setWallpaper()}

function top(){const u=me(),pendingCount=u?.isAdmin?(pendingNotifyCount??(S?.checkins||[]).filter(c=>c.status==='pending'&&c.hasProof).length):0;return `<header class="head"><button type="button" class="head-brand brand-home" data-act="homeLogo" aria-label="Gymclo — return to Home" title="Back to Home"><span class="wordmark">gymclo<i>.</i></span><span class="subtitle">THE FOUR-DAY STANDARD · ${esc(monthName(activeMonth()).toUpperCase())}</span></button><div class="head-right">${u?.isAdmin?`<button type="button" class="top-admin ${tab==='admin'?'active':''}" data-act="admin" aria-label="Open admin controls">${I('shield',17)}<span>Admin</span>${pendingCount?`<span class="admin-alert-count" title="${pendingCount} photo approvals waiting" aria-label="${pendingCount} photo approvals waiting">${pendingCount>99?'99+':pendingCount}</span>`:''}</button>`:''}<button class="icon-btn" data-act="wallpaper" aria-label="Change wallpaper" title="Wallpaper">${I('palette',19)}</button><button class="icon-btn" data-act="profile" aria-label="Your profile">${avatar(u,'sm')}</button></div></header>`}
const tabs=[['home','home','Home'],['log','log','Log'],['crew','crew','Crew'],['feed','image','Feed'],['forfeits','fire','Forfeits'],['vote','vote','Vote']];
function drawNav(){nav.hidden=!S;nav.innerHTML=S?`<div class="nav-inner">${tabs.map(([id,icon,label])=>`<button type="button" class="nav-btn ${tab===id?'on':''}" data-act="nav" data-value="${id}">${I(icon)}<span>${label}</span></button>`).join('')}</div>`:''}
function progress(c,n){const r=54,C=2*Math.PI*r,offset=C*(1-Math.min(c/n,1));return `<div class="ring-wrap"><svg viewBox="0 0 140 140" role="img" aria-label="${c} of ${n} workouts"><circle class="ring-bg" cx="70" cy="70" r="54"></circle><circle class="ring-fg" cx="70" cy="70" r="54" style="--offset:${offset}"></circle></svg><div class="ring-number"><span class="num">${c}<span style="color:var(--muted);font-size:18px">/${n}</span></span><small>this week</small></div></div>`}

const THEME_PACKS={
 'ember-luxe':{label:'Ember Luxe',desc:'Gymclo signature burgundy glow',theme:'ember',textColor:'rose',dim:.16},
 'midnight-ice':{label:'Midnight Ice',desc:'Cool blue-black with crisp text',theme:'slate',textColor:'ice',dim:.2},
 'rose-gold':{label:'Rose Gold',desc:'Warmer tones with a soft gold touch',theme:'oxide',textColor:'gold',dim:.12},
 'noir-mono':{label:'Noir Mono',desc:'Minimal blacked-out studio mode',theme:'noir',textColor:'default',dim:.24}
};
function wallpaperPackKey(){const w=setWallpaper();return Object.keys(THEME_PACKS).find(k=>{const p=THEME_PACKS[k];return !w.photo&&w.theme===p.theme&&w.textColor===p.textColor&&String(w.dim)===String(p.dim)})||''}
function cycleWeekSummary(profileId,start){return Array.from({length:4},(_,i)=>{const ws=addDays(start,i*7),count=weekCount(profileId,ws),goal=cycleRule(ws).target;return {start:ws,count,goal,done:count>=goal,label:'Week '+(i+1)}})}
function favouriteWorkout(profileId,start){const counts={};S.checkins.filter(x=>x.profileId===profileId&&x.status!=='deleted'&&x.day>=start&&x.day<=addDays(start,27)).forEach(x=>counts[x.kind]=(counts[x.kind]||0)+1);const best=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];return best?{kind:best[0],count:best[1]}:null}
function achievementCards(profileId){const start=cycleStart(today()),sum=cycleWeekSummary(profileId,start),workouts=countAll(profileId,start),days=countCycleDays(profileId,start),fav=favouriteWorkout(profileId,start),cards=[];if(weekCount(profileId,activeWeek())>=target())cards.push({icon:I('check',18),title:'Weekly target complete',desc:'You hit your '+target()+'/4 standard for this week.',value:'Locked in'});else cards.push({icon:I('spark',18),title:'Consistency in motion',desc:Math.max(0,target()-weekCount(profileId,activeWeek()))+' more day'+(Math.max(0,target()-weekCount(profileId,activeWeek()))===1?'':'s')+' until this week is complete.',value:weekCount(profileId,activeWeek())+'/'+target()});cards.push({icon:'💎👑',title:'Diamond status',desc:crowned(profile(profileId))?'You currently hold the crew MVP crown.':'MVP crown updates at the end of a voted cycle.',value:crowned(profile(profileId))?'Current MVP':'In contention'});cards.push({icon:I('clock',18),title:'Streak power',desc:'Your longest live run of completed weeks.',value:streak(profileId)+' week'+(streak(profileId)===1?'':'s')});cards.push({icon:I('log',18),title:'Four-week output',desc:fav?('Most logged session: '+fav.kind+'.'):'Start logging to build your recap.',value:workouts+' workout'+(workouts===1?'':'s')});cards.push({icon:'✦',title:'Presence',desc:'Unique gym days shown across the current cycle.',value:days+' day'+(days===1?'':'s')});return cards.slice(0,4)}
function recapStats(profileId,start){const fav=favouriteWorkout(profileId,start),workouts=countAll(profileId,start),days=countCycleDays(profileId,start),weeks=cycleWeekSummary(profileId,start),completed=weeks.filter(x=>x.done).length;return {weeks,completed,workouts,days,fav,streak:streak(profileId)}}

function todayLogged(){return S.checkins.some(c=>c.profileId===me().id&&c.day===today()&&!['deleted','rejected'].includes(c.status))}
function todaySessions(){return S.checkins.filter(c=>c.profileId===me().id&&c.day===today()&&!['rejected','deleted'].includes(c.status)).length}

let scPlayer=null,scReady=false,scPlaying=false,scApiPromise=null,scMountedFrame=null,scTrackKey="",scCurrentTitle="";
function validSoundcloudUrl(raw){try{const u=new URL(raw);return u.protocol==='https:'&&['soundcloud.com','www.soundcloud.com','m.soundcloud.com'].includes(u.hostname)&&u.pathname.split('/').filter(Boolean).length>=2}catch{return false}}
function vinylCard(){
  const track=S?.jukebox||{url:''},p=profile(track.selectedBy),has=!!track.url;
  const source=has?'https://w.soundcloud.com/player/?url='+encodeURIComponent(track.url)+'&auto_play=false&color=%23eb6975&show_artwork=false&show_user=true&sharing=false&buying=false&download=false&visual=false&show_comments=false':'';
  return `<section class="card vinyl-card" aria-label="SoundCloud vinyl music player"><div class="card-head"><div><div class="eyebrow">THE CREW'S SOUNDTRACK</div><h2 class="section-title" style="margin-top:4px">Now spinning.</h2></div><span class="pill">SoundCloud</span></div><div class="vinyl-main"><div class="turntable-stage" id="turntableStage"><button type="button" id="vinylDisc" class="vinyl-disc" data-act="vinylToggle" aria-label="${has?'Play or pause the selected track':'Choose a track to play'}" aria-pressed="false"><span class="vinyl-label"><img id="vinylArtwork" alt="" hidden><span id="vinylFallback">${I('spark',28)}</span></span><span id="vinylPlayIndicator" class="vinyl-play-indicator">▶</span></button><div class="vinyl-tonearm" id="vinylTonearm" aria-hidden="true"><svg class="tonearm-svg" viewBox="0 0 126 120" xmlns="http://www.w3.org/2000/svg" role="presentation"><defs><linearGradient id="tonearmMetal" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f4ebee"/><stop offset=".35" stop-color="#9999a2"/><stop offset=".65" stop-color="#e4dce1"/><stop offset="1" stop-color="#55515d"/></linearGradient></defs><circle cx="103" cy="18" r="14" fill="#0a090c" stroke="#504b58" stroke-width="2"/><circle cx="103" cy="18" r="9" fill="#252229" stroke="url(#tonearmMetal)" stroke-width="3"/><path d="M103 21 L102 34 Q102 39 96 44 L69 66 Q64 71 59 82" fill="none" stroke="#09080a" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/><path d="M103 21 L102 34 Q102 39 96 44 L69 66 Q64 71 59 82" fill="none" stroke="url(#tonearmMetal)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="M59 79 L54 87 L62 89 L66 82 Z" fill="#242028" stroke="#b4a6b2" stroke-width="1"/><path d="M58 87 L56 93" stroke="#f4a6ad" stroke-width="2" stroke-linecap="round"/><circle cx="103" cy="18" r="3" fill="#d6cad2"/></svg></div></div><div class="vinyl-info"><div class="label">Selected track</div><div id="vinylTitle" class="vinyl-title">${esc(has?track.title:'No track selected')}</div><p class="micro" style="margin-top:6px">${has?'Chosen by '+esc(p?.name||'a crew member'):'Anyone in the crew can choose a song.'}</p><p class="micro" id="vinylPlaybackStatus" style="margin-top:10px">${has?'Tap the vinyl to play. Tap again to pause.':'Paste a public SoundCloud link below.'}</p>${has?`<a class="vinyl-source" href="${esc(track.url)}" target="_blank" rel="noopener noreferrer">Listen on SoundCloud ↗</a>`:''}</div></div>${has?`<iframe id="soundcloudWidget" class="soundcloud-widget" title="SoundCloud audio engine (controlled by the vinyl)" src="${esc(source)}" loading="eager" allow="autoplay" referrerpolicy="strict-origin-when-cross-origin"></iframe>`:''}<form data-form="jukebox" class="vinyl-picker"><label class="field" for="soundcloudUrl">Choose a SoundCloud track or playlist</label><div class="vinyl-picker-row"><input class="input" name="url" id="soundcloudUrl" type="url" required placeholder="https://soundcloud.com/artist/song" aria-label="SoundCloud link"><button class="btn small" type="submit">Set track</button></div><div class="micro" style="margin-top:9px">Changing the track updates the crew's selection. Playback never starts automatically.</div></form><section class="radio-archive" id="radioArchive" aria-label="Previously selected SoundCloud songs"><button type="button" class="radio-toggle" data-act="radioToggle" id="radioToggle" aria-expanded="false" aria-controls="radioHistoryPanel"><span class="radio-toggle-label">Radio history <span class="pill" id="radioCount">0 songs</span></span><span class="radio-chevron" aria-hidden="true">⌄</span></button><div id="radioHistoryPanel" hidden><p class="micro" style="padding:8px 0 2px">Previously added tracks, shared by your crew.</p><label class="field" for="radioFilter">Filter by member</label><select id="radioFilter" class="input radio-filter" aria-label="Filter radio history by member"></select><div id="radioHistoryList" class="radio-list" aria-live="polite"></div></div></section></section>`
}
function updateRadioHistory(){
 const list=q('#radioHistoryList'),filter=q('#radioFilter'),count=q('#radioCount');if(!list||!filter)return;
 const panel=q('#radioHistoryPanel'),toggle=q('#radioToggle');
 if(panel)panel.hidden=!radioOpen;
 if(toggle)toggle.setAttribute('aria-expanded',String(radioOpen));
 const songs=Array.isArray(S?.radioHistory)?S.radioHistory:[];
 const authors=[...new Set(songs.map(x=>x.selectedBy).filter(Boolean))];
 if(!authors.includes(radioFilter)&&radioFilter!=='all')radioFilter='all';
 const filterValue=filter.value||radioFilter;
 const options=`<option value="all">All members</option>${authors.map(id=>`<option value="${esc(id)}">${esc(profile(id)?.name||'Former member')}</option>`).join('')}`;
 // Keep Safari's select control mounted when content has not changed.
 if(filter.innerHTML!==options)filter.innerHTML=options;
 filter.value=authors.includes(filterValue)||filterValue==='all'?filterValue:'all';radioFilter=filter.value;
 if(count)count.textContent=`${songs.length} song${songs.length===1?'':'s'}`;
 const visible=songs.filter(x=>radioFilter==='all'||x.selectedBy===radioFilter);
 list.innerHTML=visible.length?visible.map(song=>{
   const own=song.selectedBy===me()?.id,active=S.jukebox?.url===song.url&&S.jukebox?.selectedBy===song.selectedBy;
   const title=esc(song.title||'SoundCloud track');
   return `<div class="radio-row"><button type="button" class="radio-row-select ${active?'current':''}" data-act="radioSelect" data-id="${esc(song.id)}" ${active?'disabled':''} aria-label="${active?'Current track: ':'Play selection: '}${title}" ${active?'aria-current="true"':''}><span class="radio-record">${I('fire',17)}</span><span class="grow"><span class="row-name">${title}${active?' <span class="red">· Current</span>':''}</span><span class="row-sub">Added by @${esc(profile(song.selectedBy)?.name||'former member')} · ${new Date(song.updatedAt||Date.now()).toLocaleDateString('en-GB')}</span></span><span class="radio-track-state">${active?'●':'▶'}</span></button><div class="radio-controls">${own?`<button type="button" class="btn ghost small" data-act="radioDelete" data-id="${esc(song.id)}" aria-label="Remove ${title}">Remove</button>`:''}<a class="radio-open-link" href="${esc(song.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${title} on SoundCloud">↗</a></div></div>`
 }).join(''):'<p class="micro" style="padding:12px 0">No tracks found. Add the first one above.</p>';
}
function loadScApi(){if(window.SC?.Widget)return Promise.resolve();if(scApiPromise)return scApiPromise;scApiPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://w.soundcloud.com/player/api.js';script.async=true;script.onload=resolve;script.onerror=()=>{scApiPromise=null;reject(Error('SoundCloud player could not load'))};document.head.append(script)});return scApiPromise}
function setVinylPlaying(on){
 scPlaying=!!on;
 const disc=q('#vinylDisc');if(disc){disc.classList.toggle('playing',scPlaying);disc.setAttribute('aria-pressed',String(scPlaying));disc.setAttribute('aria-label',scPlaying?'Pause SoundCloud':'Play SoundCloud')}
 const arm=q('#vinylTonearm');if(arm)arm.classList.toggle('engaged',scPlaying);
 const label=q('#vinylPlaybackStatus');if(label)label.textContent=scPlaying?'Playing · tap the vinyl to pause':'Paused · tap the vinyl to play';
 const indicator=q('#vinylPlayIndicator');if(indicator)indicator.textContent=scPlaying?'Ⅱ':'▶';
 const mini=q('#music-mini');if(mini){mini.classList.toggle('playing',scPlaying);const button=q('#mini-toggle');if(button){button.textContent=scPlaying?'Ⅱ':'▶';button.setAttribute('aria-label',scPlaying?'Pause SoundCloud':'Play SoundCloud')}const status=q('#mini-status');if(status)status.textContent=scPlaying?'Playing':'Paused'}
}
function updateVinylArtwork(sound){if(!sound)return;scCurrentTitle=sound.title||scCurrentTitle;const miniTitle=q('#mini-title');if(miniTitle&&scCurrentTitle)miniTitle.textContent=scCurrentTitle;if(!q('#vinylArtwork'))return;const art=sound.artwork_url||sound.user?.avatar_url||'';if(/^https:\/\//.test(art)){const img=q('#vinylArtwork');img.src=art.replace(/-large(?=\.)/,'-t500x500');img.hidden=false;const fallback=q('#vinylFallback');if(fallback)fallback.hidden=true;}const title=q('#vinylTitle');if(title&&sound.title)title.textContent=sound.title}
function mountSoundcloud(){const frame=q('#soundcloudWidget');if(!frame){scPlayer=null;scReady=false;scMountedFrame=null;scPlaying=false;return}if(scMountedFrame===frame&&scPlayer)return;scPlayer=null;scReady=false;scPlaying=false;scMountedFrame=frame;loadScApi().then(()=>{if(!frame.isConnected||q('#soundcloudWidget')!==frame)return;const widget=window.SC.Widget(frame);scPlayer=widget;widget.bind(window.SC.Widget.Events.READY,()=>{if(q('#soundcloudWidget')!==frame)return;scReady=true;widget.getCurrentSound(updateVinylArtwork);widget.isPaused(paused=>setVinylPlaying(!paused))});widget.bind(window.SC.Widget.Events.PLAY,()=>{if(frame.isConnected){setVinylPlaying(true);widget.getCurrentSound(updateVinylArtwork)}});widget.bind(window.SC.Widget.Events.PAUSE,()=>setVinylPlaying(false));widget.bind(window.SC.Widget.Events.FINISH,()=>setVinylPlaying(false));widget.bind(window.SC.Widget.Events.ERROR,()=>{setVinylPlaying(false);const label=q('#vinylPlaybackStatus');if(label)label.textContent='Track unavailable in the embedded player. Try another song.'})}).catch(err=>{const label=q('#vinylPlaybackStatus');if(label)label.textContent=err.message})}
function toggleVinyl(){if(!S?.jukebox?.url){q('#soundcloudUrl')?.focus();toast('Paste a SoundCloud link to select a track');return}if(!scPlayer||!scReady){toast('SoundCloud is loading. Tap the vinyl again shortly.');return}if(scPlaying)scPlayer.pause();else scPlayer.play()}

let scTrackChangeTimer=null,scPendingTrack='';
function rebuildMusicDeck(deck,key){
 if(scPlayer){try{scPlayer.pause()}catch{}}
 scTrackKey=key;scCurrentTitle=S.jukebox?.title||'SoundCloud track';
 scPlayer=null;scReady=false;scMountedFrame=null;scPlaying=false;
 deck.classList.remove('changing-record');deck.innerHTML=vinylCard();
 if(key)mountSoundcloud();
}
function syncMusicDeck(){
 const deck=q('#music-deck'),mini=q('#music-mini');
 if(!S||!deck||!mini)return;
 const key=S.jukebox?.url||'';
 if(scPendingTrack&&scPendingTrack!==key){clearTimeout(scTrackChangeTimer);scTrackChangeTimer=null;scPendingTrack='';deck.classList.remove('changing-record')}
 if(scTrackKey!==key||!deck.firstElementChild){
  if(scTrackKey&&deck.firstElementChild&&key!==scTrackKey&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
   if(scPendingTrack!==key){
    scPendingTrack=key;
    // Actual audio stops immediately. The stylus lifts before loading the new record.
    if(scPlayer){try{scPlayer.pause()}catch{}}
    setVinylPlaying(false);deck.classList.add('changing-record');
    scTrackChangeTimer=setTimeout(()=>{
     scTrackChangeTimer=null;scPendingTrack='';
     if(!S||!deck.isConnected||S.jukebox?.url!==key)return;
     rebuildMusicDeck(deck,key);syncMusicDeck();
    },740);
   }
  }else rebuildMusicDeck(deck,key);
 }
 const visible=tab==='home';
 deck.classList.toggle('music-deck-parked',!visible);
 mini.hidden=visible||!key;
 if(key){mini.innerHTML=`<div class="mini-art">${I('fire',19)}</div><div class="mini-copy"><div id="mini-title" class="mini-title">${esc(scCurrentTitle||S.jukebox?.title||'SoundCloud')}</div><div id="mini-status" class="mini-sub">${scPlaying?'Playing':'Paused'} · SoundCloud</div></div><button id="mini-toggle" type="button" data-act="vinylToggle" aria-label="${scPlaying?'Pause':'Play'} SoundCloud">${scPlaying?'Ⅱ':'▶'}</button><button type="button" class="mini-home" data-act="nav" data-value="home" aria-label="Open music player">${I('arrow',17)}</button>`}
 setVinylPlaying(scPlaying);
 updateRadioHistory();
}
function home(){const meId=me().id,w=activeWeek(),c=weekCount(meId,w),n=target(),remaining=Math.max(0,n-c),remainingDays=Math.max(0,7-((dayOf(today()).getUTCDay()+6)%7)-1),ms=profiles(),total=ms.filter(p=>weekHit(p.id,w)).length,start=cycleStart(today()),recap=recapStats(meId,start),cards=achievementCards(meId),pack=wallpaperPackKey();return `${top()}<section class="card hero"><div class="hero-copy"><div class="eyebrow">YOUR WEEK AT A GLANCE</div><div class="hero-big">${c>=n?'Made it.':'Keep the pace.'}</div><p>${c>=n?'Four gym days. One standard. You showed up.':`${remaining} more gym day${remaining!==1?'s':''} to reach your target this week.`}</p><div class="hero-actions"><button class="btn small" data-act="nav" data-value="log">${I('log',15)} Log workout</button><button class="btn ghost small" data-act="wallpaper">${I('spark',15)} Theme studio</button></div><div class="streak-badge">${I('clock',13)} ${streak(meId)} week streak</div></div>${progress(c,n)}</section><section class="dashboard-grid" style="margin-top:12px"><div class="dashboard-stack"><div class="glass-tile"><div class="card-head"><div><div class="label">Cinematic home</div><div class="section-title">Your dashboard</div></div><span class="pill ${c>=n?'done':''}">${c>=n?'Target complete':'In progress'}</span></div><div class="mini-kpi"><div class="metric"><div class="label">Crew finished</div><div class="value num">${total}<span style="color:var(--muted);font-size:15px">/${ms.length}</span></div></div><div class="metric"><div class="label">Days left</div><div class="value num">${remainingDays}</div></div><div class="metric"><div class="label">Cycle weeks</div><div class="value num">${recap.completed}<span style="font-size:15px;color:var(--muted)">/4</span></div></div><div class="metric"><div class="label">Gym days</div><div class="value em num">${recap.days}</div></div></div></div><div class="glass-tile next-milestone"><div><div class="label">Next milestone</div><h3>${c>=n?'Weekly standard complete':'Close the week strong'}</h3><p class="section-desc" style="margin:7px 0 0">${c>=n?'Use the rest of the week to build momentum for the next cycle.' : `You need ${remaining} more gym day${remaining===1?'':'s'} to lock in this week.`}</p></div><div class="value num">${c>=n?'4/4':remaining}</div></div></div><div class="glass-tile home-theme-card"><div class="card-head"><div><div class="label">Curated themes</div><div class="section-title">Visual identity</div></div><span class="pill">${pack?THEME_PACKS[pack].label:'Custom'}</span></div><p class="section-desc" style="margin-top:0">Switch the entire tone of Gymclo with coordinated themes rather than piecemeal colours.</p><div class="theme-pack-grid">${Object.entries(THEME_PACKS).map(([key,p])=>`<button type="button" class="theme-pack ${pack===key?'active':''}" data-act="themePack" data-value="${key}" data-pack="${key}"><b>${esc(p.label)}</b><span>${esc(p.desc)}</span><div class="theme-pack-preview"><i></i><i></i><i></i></div></button>`).join('')}</div><div class="button-row"><button class="btn ghost small" data-act="wallpaper">Fine-tune wallpaper</button></div></div></section><div class="section-head"><h2 class="section-title">Achievement cards</h2><span class="micro">COLLECT YOUR WINS</span></div><section class="achievement-grid">${cards.map(card=>`<article class="achievement-card"><div class="achievement-icon">${card.icon}</div><div class="section-title">${esc(card.title)}</div><p>${esc(card.desc)}</p><div class="achievement-foot"><span class="achievement-value">${esc(card.value)}</span><span class="pill">Live</span></div></article>`).join('')}</section><div class="section-head"><h2 class="section-title">Four-week recap</h2><span class="micro">CURRENT CYCLE</span></div><section class="recap-grid"><div class="glass-tile"><div class="label">Weekly completion arc</div><div class="section-title" style="margin-top:4px">Consistency over four weeks</div><div class="recap-bars">${recap.weeks.map((wk,i)=>`<div class="recap-bar ${wk.done?'done':''}"><div class="track"><i style="height:${Math.max(14,Math.round((wk.count/Math.max(1,wk.goal))*100))}%"></i></div><span>Week ${i+1}<br>${wk.count}/${wk.goal}</span></div>`).join('')}</div></div><div class="recap-stats"><div class="recap-chip"><div class="label">Favourite workout</div><div class="value">${esc(recap.fav?recap.fav.kind:'—')}</div><div class="micro">${recap.fav?`${recap.fav.count} logged this cycle`:'Build a pattern to unlock this insight.'}</div></div><div class="recap-chip"><div class="label">Longest streak</div><div class="value num">${recap.streak} week${recap.streak===1?'':'s'}</div><div class="micro">Consecutive completed weeks.</div></div><div class="recap-chip"><div class="label">Total output</div><div class="value num">${recap.workouts}</div><div class="micro">Workout${recap.workouts===1?'':'s'} logged across the cycle.</div></div><div class="recap-chip"><div class="label">Current forfeit</div><div class="value" style="font-size:16px;line-height:1.2">${esc(cycleRule(w).forfeits[cycleWeek(w)]||fallback[cycleWeek(w)])}</div><div class="micro">Week ${cycleWeek(w)+1} consequence if the target is missed.</div></div></div></section><div class="section-head"><h2 class="section-title">The crew</h2><span class="micro">MON — SUN</span></div><div class="card">${ms.map(p=>{const count=weekCount(p.id,w),days=new Set(weekCheckins(p.id,w).map(x=>x.day));return `<div class="list-row">${avatar(p,'md')}<div class="grow"><div class="row-name">${displayName(p)} ${p.id===me().id?'<span class="red">· you</span>':''}</div><div class="week-pips">${Array.from({length:7},(_,i)=>{const d=addDays(w,i);return `<span class="day-pip ${days.has(d)?'hit':''} ${d===today()?'today':''}" title="${esc(fmt(d))}"></span>`}).join('')}</div></div>${pill(count,n)}</div>`}).join('')}</div>${demoMode?'<div class="support-note" style="margin-top:14px">PREVIEW MODE · demo PIN is <b>1234</b>. Entries on this file are only saved on this device.</div>':''}`}

function logPage(){const w=activeWeek(),c=weekCount(me().id,w),n=cycleRule(w).target,logged=todayLogged(),m=calendarMonth||activeMonth(),mine=S.checkins.filter(x=>x.profileId===me().id&&x.day.startsWith(m)).sort((a,b)=>b.day.localeCompare(a.day)),mineDays=new Set(mine.filter(x=>!['rejected','deleted'].includes(x.status)).map(x=>x.day)).size;return `${top()}<div class="eyebrow">WORKOUT JOURNAL</div><h1 style="font-size:29px;letter-spacing:-.06em;margin:6px 0 7px">Your attendance.</h1><p class="section-desc">A clear record of every gym day, with archives for previous months.</p><div class="card"><div class="log-head"><div><div class="label">This week</div><div class="log-count">${c}<span> / ${n}</span></div></div><span class="pill ${logged?'done':''}">${logged?'✓ Logged today':'Not logged today'}</span></div><div class="progress-mini"><i style="--pct:${Math.min(100,c/n*100)}%"></i></div><p class="micro" style="margin-top:12px">${todaySessions()} session${todaySessions()===1?'':'s'} logged today. Multiple sessions are welcome; each calendar day counts once toward your weekly target.</p><details class="log-form"><summary>${I('log',17)} Log today's workout ${I('arrow',17)}</summary><form data-form="checkin" style="padding-top:14px"><div class="label">Session type</div><div class="kind-grid">${[['push','Push'],['pull','Pull'],['legs','Legs'],['cardio','Cardio'],['other','Other']].map(([id,name])=>`<button type="button" data-act="kind" data-value="${id}" class="kind-chip ${selectedWorkout===id?'active':''}">${I(id==='cardio'?'clock':id==='other'?'spark':'log')}${name}</button>`).join('')}</div><label class="field" for="workoutNote">Notes (optional)</label><input class="input" id="workoutNote" maxlength="180" placeholder="What did you train?"><label class="field">Proof of attendance</label><div class="proof-uploader"><label class="proof-drop" for="checkinPhoto"><div class="proof-icon">${I('camera',22)}</div><div class="proof-copy"><strong id="proofUploadTitle">${formPhoto?'Image ready':'Attach workout evidence'}</strong><span>JPG, PNG or WebP · Private unless shared</span></div><span class="proof-browse">Choose image</span><input type="file" id="checkinPhoto" accept="image/*" aria-label="Select gym attendance photo"></label><div class="proof-preview ${formPhoto?'has-image':''}" id="proofPreview">${formPhoto?`<img alt="Selected proof" src="${formPhoto}"><span class="grow micro">Image attached successfully</span>`:''}<button type="button" class="proof-remove" data-act="clearProof">Remove</button></div></div><label class="share-option"><input type="checkbox" name="shareToFeed"><span><b>Share this achievement to the crew feed</b><span class="micro" style="display:block;margin-top:3px">Optional · off by default. Your photo appears only after it is approved.</span></span></label><button class="btn full" type="submit" style="margin-top:15px">Submit workout</button></form></details></div><div class="section-head"><h2 class="section-title">Attendance calendar</h2><span class="pill">${mineDays} day${mineDays===1?'':'s'}</span></div>${archivePicker(m,'calendar')}${calCard(me().id)}<div class="section-head"><h2 class="section-title">${esc(monthName(m))} sessions</h2></div><div class="card">${mine.length?mine.filter(x=>x.status!=='deleted').map(x=>`<div class="list-row"><div class="avatar md" style="background:var(--red-dim);color:var(--red-light)">${I('check',20)}</div><div class="grow"><div class="row-name">${fmt(x.day,{weekday:'short',day:'numeric',month:'short'})} · ${esc(x.kind)}</div><div class="row-sub">${esc(x.note||'Gym session')}</div></div>${x.adminAdded?'<span class="pill gold">Admin added</span>':''}${x.hasProof?`<button class="btn ghost small" data-act="proof" data-id="${x.id}">Proof</button><button class="btn outline small" data-act="shareSession" data-id="${x.id}">${x.shareToFeed?'Unshare':'Share'}</button>`:''}<span class="pill ${x.status==='rejected'?'risk':x.status==='approved'?'done':''}">${esc(x.status)}</span></div>`).join(''):'<p class="muted">No entries in this month.</p>'}</div>`}

function crewPage(){const start=cycleStart(today()),w=activeWeek(),listed=profiles().map(p=>({...p,c:weekCount(p.id,w),hits:totalHits(p.id,start),all:countAll(p.id,start),days:countCycleDays(p.id,start)})).sort((a,b)=>b.hits-a.hits||b.days-a.days||a.name.localeCompare(b.name));return `${top()}<div class="eyebrow">FOUR-WEEK CONSISTENCY</div><h1 class="section-title" style="font-size:29px;margin:7px 0">The leaderboard.</h1><p class="section-desc">Current challenge: ${fmt(start)} – ${fmt(addDays(start,27))}. Everyone is measured across exactly four weeks.</p>${crownBanner()}<div class="card">${listed.map((p,i)=>`<div class="list-row"><div class="score-rank ${i<3?'top':''}">${n2(i+1)}</div>${avatar(p,'md')}<div class="grow"><div class="row-name">${esc(p.name)} ${p.id===me().id?'<span class="red">· you</span>':''}</div><div class="row-sub">${p.hits}/4 weeks completed · ${p.days} gym day${p.days===1?'':'s'} · ${p.all} workouts</div><div class="progress-mini"><i style="--pct:${Math.min(100,Math.round(p.c/target()*100))}%"></i></div></div>${pill(p.c,target())}</div>`).join('')}</div><div class="section-head"><h2 class="section-title">Four-week highlights</h2></div><div class="metric-grid"><div class="metric"><div class="label">Crew workouts</div><div class="value num">${listed.reduce((n,x)=>n+x.all,0)}</div></div><div class="metric"><div class="label">Finished weeks</div><div class="value num">${listed.reduce((n,x)=>n+x.hits,0)}</div></div><div class="metric"><div class="label">Perfect cycles</div><div class="value em num">${listed.filter(x=>eligible(x.id,start)).length}</div></div></div><div class="section-head"><h2 class="section-title">Your calendar</h2></div>${calCard(me().id)}`}
const messageGifUrl=m=>m?.gifId?`https://giphy.com/embed/${esc(m.gifId)}`:'';
const handle=p=>'@'+(p?.name||'member').toLowerCase().replace(/[^a-z0-9]+/g,'').slice(0,25);
function messageCard(m,replies=[]){const p=profile(m.profileId),own=me()?.id===m.profileId;return `<article class="${m.parentId?'chat-reply':'card chat-card'}"><div class="chat-author">${avatar(p,'sm')}<div class="grow"><div class="feed-handle">${esc(handle(p))} ${crowned(p)?'💎👑':''}</div><div class="micro">${new Date(m.createdAt).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}${m.editedAt?' · edited':''}</div></div>${own?`<button class="btn ghost small" data-act="editChat" data-id="${m.id}">${I('pen',14)} Edit</button><button class="btn ghost small" data-act="deleteChat" data-id="${m.id}" style="color:var(--red-light)">${I('x',14)} Delete</button>`:''}</div>${m.text?`<p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(m.text)}</p>`:''}${m.hasImage?`<img class="chat-photo" src="/api/messages/${m.id}/image" loading="lazy" alt="Image attached by ${esc(handle(p))}">`:''}${m.gifId?`<iframe title="GIF reply from GIPHY" class="gif-frame" loading="lazy" src="${messageGifUrl(m)}" allowfullscreen></iframe><div class="micro">Powered by GIPHY</div>`:''}<div class="chat-actions">${m.reactions.map(r=>`<button class="reaction ${m.myReaction===r.emoji?'selected':''}" data-act="chatReact" data-id="${m.id}" data-value="${r.emoji}">${r.emoji} ${r.count||''}</button>`).join('')}${!m.parentId?`<button class="btn ghost small" data-act="replyChat" data-id="${m.id}">${I('log',13)} Reply ${replies.length?`(${replies.length})`:''}</button>`:''}</div>${replies.length?`<div class="chat-replies">${replies.map(x=>messageCard(x)).join('')}</div>`:''}</article>`}
function chatBoard(){const messages=S.messages||[],roots=messages.filter(m=>!m.parentId),replies=messages.filter(m=>m.parentId);return `<div class="section-head" style="margin-top:2px"><h2 class="section-title">Crew chat</h2><span class="pill">Everyone can post</span></div><div class="card chat-composer"><form data-form="chatPost"><label class="field" for="chatText">Say something to the crew</label><textarea id="chatText" name="text" class="input" maxlength="1000" placeholder="What's happening today? Share a win, a plan, or just a thought…"></textarea><div class="chat-composer-inputs"><label class="micro">Attach an image<input type="file" class="input" name="image" accept="image/*"></label><label class="micro">GIF link (optional)<input class="input" name="gifUrl" placeholder="Paste a GIPHY link"></label></div><button class="btn full" type="submit">Post to crew chat</button></form><div class="micro" style="margin-top:11px">Messages are visible to all signed-in members. Edit or delete your posts at any time.</div></div>${roots.length?roots.map(m=>messageCard(m,replies.filter(x=>x.parentId===m.id))).join(''):'<div class="support-note">No messages yet — start the conversation.</div>'}<div class="divider"></div>`}
function chatModal(parentId='',id=''){const message=(S.messages||[]).find(m=>m.id===id),isReply=!!parentId;const currentGif=message?.gifId?`https://giphy.com/embed/${message.gifId}`:'';openModal({title:id?'Edit your message':isReply?'Reply to the crew':'New message',body:`<form data-form="${id?'chatEdit':'chatPost'}" data-id="${esc(id)}" data-parent="${esc(parentId||message?.parentId||'')}"><label class="field">Message</label><textarea class="input" name="text" maxlength="1000" rows="4" placeholder="Your message…">${esc(message?.text||'')}</textarea><label class="field">Attach photo ${message?.hasImage?'(replace existing photo if needed)':''}</label><input class="input" type="file" name="image" accept="image/*">${message?.hasImage?'<label class="micro"><input type="checkbox" name="removeImage"> Remove existing photo</label>':''}<label class="field">GIPHY reaction</label><input class="input" name="gifUrl" id="gifInput" value="${esc(currentGif)}" placeholder="Paste a giphy.com/gifs/... link">${S.giphyEnabled?`<label class="field">Search GIPHY</label><div class="chat-composer-inputs"><input class="input" id="gifSearch" placeholder="Search GIFs…"><button class="btn ghost" type="button" data-act="gifSearch">Search</button></div><div class="gif-search-results" id="gifResults"></div><div class="micro">Powered by GIPHY</div>`:'<div class="micro" style="margin-top:8px">Find a GIF on GIPHY and paste its share link above. In-app searching can be enabled with a GIPHY API key.</div>'}<button class="btn full" type="submit" style="margin-top:13px">${id?'Save changes':'Post reply'}</button></form>`})}
function feedPage(){const items=S.feed||[];return `${top()}${chatBoard()}<div class="eyebrow">SHOW UP. SHARE THE WIN.</div><h1 class="section-title" style="font-size:29px;margin:7px 0">The crew feed.</h1><p class="section-desc">Only achievements members choose to share appear here. Photos stay private by default and posts appear after approval.</p>${items.length?items.map(post=>{const p=profile(post.profileId),handle='@'+(p?.name||'member').toLowerCase().replace(/[^a-z0-9]+/g,'').slice(0,25);const src=demoMode?D?.proofs?.[post.id]:`/api/feed/${post.id}/image`;return `<article class="card feed-card"><div class="feed-intro">${avatar(p,'md')}<div class="grow"><div class="feed-handle">${esc(handle)}</div><div class="micro">${displayName(p)} · ${fmt(post.day,{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</div></div><span class="pill done">${esc(post.kind)}</span></div>${src?`<img class="feed-media" src="${esc(src)}" alt="Gym achievement shared by ${esc(p?.name||'member')}" loading="lazy">`:''}<div class="feed-content">${post.note?`<p>${esc(post.note)}</p>`:''}<div class="feed-reactions">${post.reactions.map(r=>`<button type="button" class="reaction ${post.myReaction===r.emoji?'selected':''}" data-act="react" data-id="${post.id}" data-value="${r.emoji}" aria-label="React ${r.emoji}, ${r.count} reactions">${r.emoji} <span class="micro">${r.count||''}</span></button>`).join('')}</div></div></article>`}).join(''):'<div class="card"><div class="section-title">No public achievements yet.</div><p class="section-desc" style="margin-top:8px">When logging a gym photo, tick “Share this achievement” to post it to the feed after approval.</p><button class="btn small" data-act="nav" data-value="log">Go to Log</button></div>'}`}

function calCard(id){const month=calendarMonth||activeMonth(),[y,mo]=month.split('-').map(Number),days=new Date(Date.UTC(y,mo,0)).getUTCDate(),offset=(dayOf(`${month}-01`).getUTCDay()+6)%7,hits=new Set(S.checkins.filter(x=>x.profileId===id&&x.status!=='rejected'&&x.status!=='deleted').map(x=>x.day));return `<div class="card"><div class="card-head"><button class="icon-btn" data-act="cal" data-value="-1" aria-label="Previous month">${I('back',17)}</button><h3 class="section-title">${monthName(month)}</h3><button class="icon-btn" data-act="cal" data-value="1" aria-label="Next month" ${month>=activeMonth()?'disabled':''}>${I('arrow',17)}</button></div><div class="calendar">${['M','T','W','T','F','S','S'].map(x=>`<div class="cal-h">${x}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=`${month}-${n2(i+1)}`;return `<div class="cal-day ${hits.has(d)?'hit':''} ${d===today()?'today':''}" style="animation-delay:${Math.min(i,21)*15}ms">${i+1}</div>`}).join('')}</div></div>`}
function forfeitsPage(){const start=forfeitView||cycleStart(today()),weeks=cycleDates(start),r=cycleRule(start),owe=profiles().flatMap(p=>weeks.filter(w=>isDoneWeek(w,today())&&!weekHit(p.id,w)&&!forfeitDone(p.id,w)).map(w=>({p,w,index:weeks.indexOf(w)})));return `${top()}<div class="eyebrow">THE FOUR-WEEK CHALLENGE</div><h1 class="section-title" style="font-size:29px;margin:7px 0">Forfeit ladder.</h1><p class="section-desc">Four increasingly difficult fitness forfeits. The ladder resets after every four-week cycle; past cycles stay archived.</p><div class="card-head"><button class="btn ghost small" data-act="cycle" data-value="${addDays(start,-28)}">${I('back',15)} Previous</button><span class="pill">${fmt(start)} – ${fmt(addDays(start,27))}</span><button class="btn ghost small" data-act="cycle" data-value="${addDays(start,28)}" ${start>=cycleStart(today())?'disabled':''}>Next ${I('arrow',15)}</button></div><div class="ladder">${weeks.map((w,i)=>`<div class="forfeit-item ${w===activeWeek()?'active':''}"><div class="step-num">${i+1}</div><div class="grow"><div class="label">Week ${i+1} · ${fmt(w)} – ${fmt(addDays(w,6))}</div><div class="step-text">${esc(r.forfeits[i]||fallback[i])}</div><div class="micro" style="margin-top:7px">${w===activeWeek()?'Current week':isDoneWeek(w,today())?'Finished':'Upcoming'}</div></div></div>`).join('')}</div><div class="section-head"><h2 class="section-title">Outstanding forfeits</h2><span class="pill risk">${owe.length} due</span></div><div class="card">${owe.length?owe.map(x=>`<div class="list-row">${avatar(x.p,'md')}<div class="grow"><div class="row-name">${esc(x.p.name)} · Week ${x.index+1}</div><div class="row-sub">${esc(r.forfeits[x.index]||fallback[x.index])}</div></div>${me().isAdmin?`<button class="btn ghost small" data-act="markForfeit" data-id="${x.p.id}" data-value="${x.w}">Mark done</button>`:'<span class="pill risk">Due</span>'}</div>`).join(''):'<p class="muted">No outstanding forfeits for this cycle.</p>'}</div><div class="support-note" style="margin-top:15px">Fitness forfeits must be appropriate to each person's health and ability. Waive or adapt them when necessary.</div>`}

function votePage(){
 const current=cycleStart(today()),past=addDays(current,-28),next=addDays(current,28);
 const mvpCandidates=profiles().filter(p=>eligible(p.id,past));
 const mine=S.mvpVotes.find(x=>x.start===past&&x.voterId===me().id);
 const votes=S.mvpVotes.filter(x=>x.start===past);
 const proposals=S.proposals.filter(p=>p.start===next&&Array.isArray(p.forfeits)&&p.forfeits.length===4);
 const myProposal=S.proposalVotes.find(x=>x.start===next&&x.voterId===me().id);
 const nomineeRows=mvpCandidates.map(p=>{const n=votes.filter(v=>v.candidateId===p.id).length;let action='';if(mine){if(mine.candidateId===p.id)action='<span class="pill done">Your vote ✓</span>'}else if(p.id===me().id)action='<span class="pill">You</span>';else action=`<button class="btn small" data-act="mvp" data-id="${p.id}" data-value="${past}">Vote</button>`;return `<div class="vote-option">${avatar(p,'md')}<div class="grow"><div class="row-name">${displayName(p)}</div><div class="row-sub">${n} vote${n===1?'':'s'} · perfect four-week attendance</div></div>${action}</div>`}).join('');
 const proposalRows=proposals.map(p=>{const count=S.proposalVotes.filter(x=>x.proposalId===p.id).length,total=S.proposalVotes.filter(x=>x.start===next).length;const adminAction=me().isAdmin?`<button class="btn outline small" data-act="applyProposal" data-id="${p.id}">Apply</button>`:'';return `<div class="vote-option"><div class="grow"><div class="row-name">${esc(p.title)}</div><div class="row-sub">Proposed by ${esc(profile(p.profileId)?.name||'Member')} · ${count} votes</div><div class="micro" style="margin-top:8px">W1 ${esc(p.forfeits[0])} … W4 ${esc(p.forfeits[3])}</div>${total?`<div class="progress-mini"><i style="--pct:${count/total*100}%"></i></div>`:''}</div><div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><button class="btn ${myProposal?.proposalId===p.id?'':'ghost'} small" data-act="proposalVote" data-id="${p.id}">${myProposal?.proposalId===p.id?'Voted ✓':'Vote'}</button>${adminAction}</div></div>`}).join('');
 return `${top()}<div class="eyebrow">A LITTLE HEALTHY COMPETITION</div><h1 class="section-title" style="font-size:29px;margin:7px 0">The voting room.</h1><p class="section-desc">Vote for a member who completed all four weeks, and choose the next set of four forfeits.</p><div class="card"><div class="card-head"><div><div class="eyebrow">THE CROWN</div><h2 class="section-title">Gym MVP · ${fmt(past)} – ${fmt(addDays(past,27))}</h2></div>${I('crown',29)}</div>${crownBanner()}${nomineeRows||'<div class="support-note">MVP nominees must complete the full previous four-week cycle.</div>'}${mine?'<p class="micro" style="margin-top:12px">One MVP vote per member. A clear winner is crowned once all claimed members have voted, or the admin finalizes the result.</p>':''}</div><div class="section-head"><h2 class="section-title">Next four-week forfeits</h2><span class="pill">${fmt(next)} – ${fmt(addDays(next,27))}</span></div><div class="card"><div class="card-head"><div class="micro">Every proposal has exactly four fitness challenges.</div><button class="btn outline small" data-act="propose">${I('log',14)} Propose</button></div>${proposalRows||'<p class="muted">No ideas yet. Submit a four-week challenge.</p>'}</div>`;
}

function adminPage(){const w=activeWeek(),pend=S.checkins.filter(c=>c.status==='pending').sort((a,b)=>Number(b.flagged||0)-Number(a.flagged||0)||b.createdAt-a.createdAt),m=adminMonth||activeMonth(),r=rule(m),ms=profiles();return `${top()}<div class="section-head"><h1 style="font-size:27px;letter-spacing:-.05em">Admin control room.</h1><span class="pill">OWNER ONLY</span></div>${crownBanner()}<div class="section-head"><h2 class="section-title">Diamond Crown MVP</h2><span class="pill">💎 ONE CURRENT MVP</span></div><div class="card"><p class="section-desc">Choose an initial MVP or award the crown manually in exceptional circumstances. Only one member holds it at a time; the crown stays until replaced.</p><form data-form="setMvpCrown" class="mvp-admin-controls"><div><label class="field">Crown this member</label><select class="input" name="profileId" required>${ms.map(p=>`<option value="${esc(p.id)}" ${S.mvpCrown?.profileId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><button class="btn" type="submit">💎 Award crown</button></form><div class="divider"></div><div class="label">Completed cycle results</div><p class="micro" style="margin:8px 0 12px">Finalize the previous cycle's MVP votes. A tied vote requires manually selecting the winner above.</p><button type="button" class="btn outline small" data-act="finalizeMvp" data-value="${addDays(cycleStart(today()),-28)}">${I('crown',15)} Crown last cycle's vote winner</button></div><p class="section-desc">Edit the current four-week forfeits below. Changes save for everyone immediately.</p><div class="section-head"><h2 class="section-title">Edit forfeits & rules</h2></div><form class="card" data-form="cycleRules"><p class="section-desc">Each cycle lasts exactly 28 days. Edit the four forfeits; the ladder automatically resets to Week 1 in the next cycle. Previous cycles remain saved.</p><label class="field">Cycle</label><select class="input" name="start" data-archive="adminCycle">${archiveCycles().map(d=>`<option value="${d}" ${d===(adminCycle||cycleStart(today()))?'selected':''}>${fmt(d)} – ${fmt(addDays(d,27))}</option>`).join('')}</select><label class="field">Distinct gym days per week</label><input class="input" name="target" type="number" min="1" max="7" required value="${cycleRule(adminCycle||cycleStart(today())).target}">${cycleRule(adminCycle||cycleStart(today())).forfeits.slice(0,4).map((f,i)=>`<label class="field">Week ${i+1} forfeit</label><input class="input" name="f${i}" maxlength="180" required value="${esc(f)}">`).join('')}<button class="btn full" style="margin-top:17px" type="submit">Save four-week forfeits</button></form><div class="section-head"><h2 class="section-title">Add a missed gym session</h2></div><form class="card" data-form="adminCheckin"><p class="section-desc">Backdate extra sessions for members who couldn't log in time. Multiple sessions per day are allowed, but that day counts only once. This is recorded as an admin correction, with no photo or feed post.</p><label class="field">Member</label><select class="input" name="profileId" required>${ms.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><label class="field">Session date</label><input class="input" type="date" name="day" max="${today()}" value="${today()}" required><label class="field">Workout type</label><select class="input" name="kind">${[['push','Push'],['pull','Pull'],['legs','Legs'],['cardio','Cardio'],['other','Other']].map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select><label class="field">Reason or notes (optional)</label><input class="input" name="note" maxlength="180" placeholder="Attendance entered by admin"><button class="btn full" style="margin-top:16px" type="submit">Save missed session</button></form><div class="card"><div class="card-head"><h3 class="section-title">Invite & manage profiles</h3><button class="btn small" data-act="addMember">${I('log',14)} Add member</button></div><p class="section-desc">Your friends need the website link, their own profile, and an invitation code to create a private PIN.</p><button type="button" class="btn outline small" data-act="copyLink">${I('copy',14)} Copy website link</button><div class="divider"></div>${ms.map(p=>`<div class="list-row">${avatar(p,'md')}<div class="grow"><div class="row-name">${esc(p.name)}</div><div class="row-sub">${p.isAdmin?'Owner':p.claimed?'PIN active':'Awaiting invitation'}</div></div><button class="btn ghost small" data-act="editMember" data-id="${p.id}">Edit</button>${!p.isAdmin?`<button class="btn outline small" data-act="resetPin" data-id="${p.id}">Reset PIN</button>`:''}</div>`).join('')}</div><div class="section-head"><h2 class="section-title">Evidence review</h2><span class="pill ${pend.length?'risk':''}">${pend.length} pending</span></div><div class="card"><p class="section-desc">Sessions count provisionally. Possible reused photos appear first; review those and anything else that looks suspicious.</p>${pend.slice(0,35).map(c=>`<div class="list-row">${avatar(profile(c.profileId),'sm')}<div class="grow"><div class="row-name">${esc(profile(c.profileId)?.name)} · ${fmt(c.day)}</div><div class="row-sub">${esc(c.note||c.kind)} ${c.flagged?'<span class="red"> · Possible reused photo</span>':''}</div></div><button class="btn ghost small" data-act="proof" data-id="${c.id}">Proof</button><button class="btn ghost small" data-act="review" data-id="${c.id}" data-value="approved">✓</button><button class="btn outline small" data-act="review" data-id="${c.id}" data-value="rejected">✕</button></div>`).join('')||'<p class="muted">Nothing to review.</p>'}</div><div class="section-head"><h2 class="section-title">Manage approved sessions</h2><span class="pill">${S.checkins.filter(c=>c.status==='approved').length} approved</span></div><div class="card"><p class="section-desc">Remove incorrect or duplicate approved sessions. Attendance credit is only removed when no other active sessions remain on that day. An audit record is preserved.</p><label class="field">Approved sessions from</label><select class="input" data-archive="approvedMonth" aria-label="Choose month to manage sessions">${archiveMonths().map(m=>`<option value="${m}" ${m===(approvedMonth||activeMonth())?'selected':''}>${monthName(m)}</option>`).join('')}</select><div class="divider"></div>${S.checkins.filter(c=>c.status==='approved'&&c.day.startsWith(approvedMonth||activeMonth())).sort((a,b)=>b.day.localeCompare(a.day)||b.createdAt-a.createdAt).map(c=>`<div class="list-row">${avatar(profile(c.profileId),'sm')}<div class="grow"><div class="row-name">${esc(profile(c.profileId)?.name||'Member')} · ${fmt(c.day)}</div><div class="row-sub">${esc(c.kind)}${c.adminAdded?' · Admin added':''}${c.note?' · '+esc(c.note):''}</div></div><button type="button" class="btn outline small" data-act="deleteSession" data-id="${c.id}">Delete</button></div>`).join('')||'<p class="muted">No approved sessions.</p>'}</div><div class="section-head"><h2 class="section-title">WhatsApp update</h2></div><div class="card"><p class="section-desc">Ready-to-paste weekly summary. You can send it directly to your WhatsApp group.</p><textarea class="input" id="summaryText" rows="10" readonly>${esc(summaryText())}</textarea><div class="button-row"><button class="btn" data-act="copySummary">${I('check',16)} Copy summary</button><button class="btn ghost" data-act="shareSummary">Share</button></div></div>`}
function summaryText(){const w=activeWeek(),r=cycleRule(w),n=r.target;return `🏋️ gymclo · Week of ${fmt(w)}\n\n${profiles().map(p=>`${weekCount(p.id,w)>=n?'✅':'⏳'} ${p.name}: ${weekCount(p.id,w)}/${n}`).join('\n')}\n\n🔥 This week's forfeit: ${r.forfeits[cycleWeek(w)]||r.forfeits[0]}\n\nLog your gym sessions: ${demoMode?'[add live link here]':location.origin}`}

function render(){setWallpaper();if(!S){clearTimeout(scTrackChangeTimer);scTrackChangeTimer=null;scPendingTrack='';nav.hidden=true;q('#music-mini').hidden=true;q('#music-deck').innerHTML='';scTrackKey='';scPlayer=null;scReady=false;return}let content=({home,log:logPage,crew:crewPage,feed:feedPage,forfeits:forfeitsPage,vote:votePage,admin:adminPage}[tab]||home)();el.innerHTML=content;drawNav();entry.hidden=true;nav.hidden=false;syncMusicDeck()}
async function refresh(){S=await api('/api/state');pendingNotifyCount=S.me?.isAdmin?S.checkins.filter(c=>c.status==='pending'&&c.hasProof).length:null;B={...B,profiles:S.profiles,me:S.me,today:S.today};render()}
async function boot(){setWallpaper();try{B=await api('/api/bootstrap');if(B.me){await refresh()}else{S=null;nav.hidden=true;renderEntry()}}catch(err){entry.hidden=false;entry.innerHTML=`<div class="entry-brand">gymclo<span class="red">.</span></div><div class="entry-title">Can't connect yet</div><p class="entry-sub">${esc(err.message)}. Check that the server is running.</p><button class="btn" style="margin-top:20px" data-act="reload">Try again</button>`}}
function renderEntry(){entry.hidden=false;nav.hidden=true;el.innerHTML='';entry.classList.remove('roulette-spinning','roulette-exit');delete entry.dataset.spinning;if(B.setupRequired)return renderSetup();if(pin.id)return renderPin();const p=B.profiles;entry.innerHTML=`<div class="entry-brand">gymclo<span class="red">.</span></div><div class="eyebrow" style="margin-top:11px">YOUR CREW. YOUR CONSISTENCY.</div><h1 class="entry-title">Who's showing up?</h1><p class="entry-sub">Choose your profile to continue</p><div class="roulette-stage" style="${p.length>10?'--roulette-bubble:clamp(44px,min(15.2vw,8.3dvh),65px)':''}" aria-label="Gymclo member roulette selector"><div class="roulette-aura" aria-hidden="true"></div><div class="roulette-wheel" id="profileGallery" role="group" aria-label="Choose a Gymclo member">${p.map((m,i)=>{const ring=Math.floor(i/12),start=ring*12,ringCount=Math.min(12,p.length-start),angle=(360*(i-start)/ringCount);return `<button type="button" class="profile-tile roulette-profile" style="--i:${i};--angle:${angle}deg;--counter-angle:${-angle}deg;--ring:${ring};--rad:${ring===0?'var(--roulette-radius)':ring===1?'calc(var(--roulette-radius) * .44)':'calc(var(--roulette-radius) * .2)'};--slot-size:${ring===0?'var(--roulette-bubble)':'calc(var(--roulette-bubble) * .72)'}" data-act="chooseProfile" data-id="${esc(m.id)}" data-index="${i}" data-angle="${angle}" aria-label="Choose ${esc(m.name)}. ${m.claimed?'Enter PIN':'Invite required'}">${avatar(m,'xl')}<span class="profile-name">${esc(m.name)}</span><span class="micro">${m.claimed?'Enter PIN':'Invite required'}</span></button>`}).join('')}</div><div class="roulette-hub" aria-hidden="true"><span class="roulette-hub-mark">g<span>.</span></span></div></div><p class="selector-foot">Tap a bubble to spin · Hold to reveal a name</p><p class="micro" style="max-width:350px;text-align:center;margin-top:12px">New here? Ask your Gymclo admin to add your profile and send you a personal invitation code. You can then create your own four-digit PIN.</p>${demoMode?'<p class="support-note" style="margin-top:17px">DEMO ONLY · PIN for the sample profiles is <b>1234</b>.</p>':''}`;}
function renderSetup(){entry.innerHTML=`<div class="setup"><div class="entry-brand">gymclo<span class="red">.</span></div><div class="eyebrow" style="margin-top:16px">WELCOME TO YOUR NEW CLUB</div><h1 class="entry-title">Start the crew.</h1><p class="entry-sub">Create the admin profile first, then invite your friends. Only the creator needs the one-time setup code from the hosting dashboard.</p><form data-form="setup" style="margin-top:24px"><label class="field">Your name</label><input class="input" name="name" maxlength="28" required autocomplete="name" placeholder="Your name"><label class="field">One-time setup code</label><input class="input" name="setupCode" required placeholder="From hosting environment"><label class="field">Choose your four-digit PIN</label><input class="input" name="pin" inputmode="numeric" type="password" minlength="4" maxlength="4" pattern="[0-9]{4}" required placeholder="••••" autocomplete="new-password"><button class="btn full" style="margin-top:18px">Create gymclo</button></form></div>`}
let rouletteTimer=null;
function chooseProfile(id,index){
 if(entry.dataset.spinning==='true')return;
 selection=Number(index)||0;
 const p=B?.profiles?.find(x=>x.id===id);if(!p)return;
 pin={id,mode:p.claimed?'enter':'claim',buf:'',first:'',claimCode:'',busy:false};
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){renderPin();return}
 const wheel=q('#profileGallery',entry),clicked=qa('.roulette-profile',entry).find(t=>t.dataset.id===id);
 if(!wheel||!clicked){renderPin();return}
 entry.dataset.spinning='true';
 entry.classList.add('roulette-spinning');
 clicked.classList.add('chosen');
 const angle=Number(clicked.dataset.angle)||0;
 // Two complete revolutions and a final alignment of the selected portrait at 12 o'clock.
 wheel.style.setProperty('--spin-to',`${1080-angle}deg`);
 clearTimeout(rouletteTimer);
 rouletteTimer=setTimeout(()=>{if(pin.id!==id)return;entry.classList.add('roulette-exit');rouletteTimer=setTimeout(()=>{if(pin.id!==id)return;entry.classList.remove('roulette-spinning','roulette-exit');delete entry.dataset.spinning;renderPin()},400)},1000);
}

function renderPin(){const p=B.profiles.find(x=>x.id===pin.id);if(!p){pin.id='';return renderEntry()}const mode=pin.mode,claim=mode==='claim',titles={enter:'Welcome back.',claim:'Claim your place.',create:'Create your PIN.',confirm:'One more time.'};entry.innerHTML=`<div class="pin-card">${avatar(p,'xxl')}<div class="entry-title" style="margin-top:25px">${esc(p.name)}</div><div class="entry-sub">${titles[mode]||titles.enter}</div>${claim?`<p class="entry-sub" style="margin-top:17px">Enter the private invitation code shared by your admin.</p><form data-form="claimCode" style="max-width:300px"><input class="input claim-code" name="code" required maxlength="48" placeholder="INVITATION CODE" autocapitalize="characters" autocomplete="off"><button class="btn full" style="margin-top:9px">Continue</button></form>`:`<div class="entry-sub" style="margin-top:8px" id="pinHelp">${mode==='confirm'?'Repeat your new four digits':mode==='create'?'Choose four digits only you know':'Enter your four-digit passcode'}</div><div class="pin-dots" id="pinDots">${Array.from({length:4},()=>'<span class="pin-dot"></span>').join('')}</div><div class="pin-pad">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(d=>d===''?'<span class="pin-key empty"></span>':`<button type="button" class="pin-key" data-act="pinDigit" data-value="${d}">${d}</button>`).join('')}</div>`}<button class="pin-back" data-act="backToProfiles">‹ Switch profile</button></div>`}
function updateDots(){qa('.pin-dot').forEach((d,i)=>d.classList.toggle('filled',i<pin.buf.length))}
async function digit(d){if(!pin.id||pin.busy||pin.mode==='claim')return;if(d==='⌫')pin.buf=pin.buf.slice(0,-1);else if(/^\d$/.test(d)&&pin.buf.length<4)pin.buf+=d;updateDots();if(pin.buf.length!==4)return;pin.busy=true;await new Promise(r=>setTimeout(r,200));const buf=pin.buf;try{if(pin.mode==='create'){pin.first=buf;pin.mode='confirm';pin.buf='';pin.busy=false;renderPin();return}if(pin.mode==='confirm'){if(buf!==pin.first){pin.mode='create';pin.first='';throw Error('PINs did not match. Try again.')}await api('/api/claim','POST',{profileId:pin.id,claimCode:pin.claimCode,pin:buf});await signedIn();return}await api('/api/login','POST',{profileId:pin.id,pin:buf});await signedIn()}catch(err){q('#pinDots')?.classList.add('shake');toast(err.message);await new Promise(r=>setTimeout(r,350));pin.buf='';pin.busy=false;updateDots();if(pin.mode==='create'&&!pin.first)renderPin()}}
async function signedIn(){const p=B.profiles.find(x=>x.id===pin.id);entry.innerHTML=`<div class="pin-card" style="animation:zoom .48s var(--ease)"><div style="border:3px solid var(--red);padding:10px;border-radius:50%;box-shadow:0 0 55px rgba(235,105,117,.23)">${avatar(p,'xxl')}</div><div class="entry-title" style="font-size:30px">You're in.</div><div class="entry-sub">Welcome to gymclo, ${esc(p.name)}.</div></div>`;pin={id:'',mode:'enter',buf:'',first:'',busy:false};await new Promise(r=>setTimeout(r,760));tab='home';await refresh()}
async function imageFile(file,max=700,q=.74){if(!file)return '';if(!file.type.startsWith('image/'))throw Error('Please select an image');const blob=URL.createObjectURL(file);try{const im=new Image();im.src=blob;try{await im.decode()}catch{throw Error('This photo format cannot be opened. Try JPG, PNG or WebP (convert HEIC to JPG if necessary).')}const scale=Math.min(1,max/Math.max(im.width,im.height));const can=document.createElement('canvas');can.width=Math.max(1,Math.floor(im.width*scale));can.height=Math.max(1,Math.floor(im.height*scale));can.getContext('2d').drawImage(im,0,0,can.width,can.height);const out=can.toDataURL('image/jpeg',q);if(out.length>600000)throw Error('Image too large. Try a smaller one.');return out}finally{URL.revokeObjectURL(blob)}}

function avatarCropClamp(value,min,max){return Math.min(max,Math.max(min,value))}
function avatarCropDimensions(){const state=avatarCropState;if(!state?.image)return null;const turned=state.turn%2!==0;
 const width=turned?state.image.naturalHeight:state.image.naturalWidth;
 const height=turned?state.image.naturalWidth:state.image.naturalHeight;
 const factor=Math.max(320/width,320/height)*state.zoom;
 return {factor,width:width*factor,height:height*factor};}
function avatarCropDraw(){const st=avatarCropState,canvas=document.getElementById('avatar-crop-canvas');if(!st?.image||!canvas)return;
 const dim=avatarCropDimensions();st.panX=avatarCropClamp(st.panX,-Math.max(0,(dim.width-320)/2),Math.max(0,(dim.width-320)/2));
 st.panY=avatarCropClamp(st.panY,-Math.max(0,(dim.height-320)/2),Math.max(0,(dim.height-320)/2));
 const ctx=canvas.getContext('2d');ctx.clearRect(0,0,320,320);ctx.fillStyle='#382633';ctx.fillRect(0,0,320,320);
 ctx.save();ctx.translate(160+st.panX,160+st.panY);ctx.rotate(st.turn*Math.PI/2);
 ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(st.image,-st.image.naturalWidth*dim.factor/2,-st.image.naturalHeight*dim.factor/2,st.image.naturalWidth*dim.factor,st.image.naturalHeight*dim.factor);ctx.restore();
}
function avatarCropClose(){avatarCropLayer.hidden=true;avatarCropLayer.innerHTML='';avatarCropState=null;avatarCropPinch=null;
 if(avatarCropSourceUrl){URL.revokeObjectURL(avatarCropSourceUrl);avatarCropSourceUrl='';}}
async function avatarCropOpen(source){avatarCropClose();
 const src=typeof source==='string'?source:URL.createObjectURL(source);if(typeof source!=='string')avatarCropSourceUrl=src;
 avatarCropLayer.hidden=false;avatarCropLayer.innerHTML=`<div class="avatar-crop-dialog" role="dialog" aria-modal="true" aria-label="Frame profile photo"><div class="avatar-crop-head"><h2>Frame your photo.</h2><button class="modal-close" type="button" data-act="cancelAvatarCrop" aria-label="Cancel photo crop">×</button></div><p class="section-desc">Drag to position your photo. Pinch or use the slider to zoom. The circle is exactly how your profile will appear.</p><div class="avatar-crop-stage"><canvas class="avatar-crop-canvas" id="avatar-crop-canvas" width="320" height="320" aria-label="Drag to move profile image"></canvas></div><label class="field" for="avatar-crop-zoom">Zoom</label><div class="avatar-crop-zoom-row">${I('image',19)}<input type="range" class="input" id="avatar-crop-zoom" min="1" max="3.5" step="0.01" value="1" aria-label="Zoom profile photo">${I('spark',19)}</div><div class="avatar-crop-actions"><button type="button" class="btn ghost small" data-act="rotateAvatarCrop">↻ Rotate</button><button type="button" class="btn ghost small" data-act="resetAvatarCrop">Recenter</button></div><div class="button-row" style="display:grid;grid-template-columns:1fr 1fr;margin-top:20px"><button type="button" class="btn ghost" data-act="cancelAvatarCrop">Cancel</button><button type="button" class="btn" data-act="saveAvatarCrop">Use photo ${I('check',16)}</button></div></div>`;
 const img=new Image();img.decoding='async';
 try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('This image cannot be opened. Try a JPG, PNG or a photo from your iPhone.'));img.src=src;if(img.complete&&img.naturalWidth)resolve();});
 if(avatarCropLayer.hidden)return;avatarCropState={image:img,zoom:1,panX:0,panY:0,turn:0,pointers:new Map(),dragPoint:null};avatarCropDraw();}
 catch(e){avatarCropClose();throw e;}
}
function avatarCropSave(){if(!avatarCropState?.image)throw Error('Choose a photo first');avatarCropDraw();
 const source=document.getElementById('avatar-crop-canvas');const output=document.createElement('canvas');output.width=320;output.height=320;
 const ctx=output.getContext('2d');ctx.fillStyle='#382633';ctx.fillRect(0,0,320,320);ctx.drawImage(source,0,0);
 let data=output.toDataURL('image/jpeg',.85);if(data.length>680000)data=output.toDataURL('image/jpeg',.67);
 if(data.length>680000)throw Error('Photo too large; try a different image');croppedAvatarData=data;
 const avatarEl=document.querySelector('.member-avatar-preview .avatar');if(avatarEl)avatarEl.innerHTML=`<img src="${data}" alt="Your cropped profile picture">`;
 const note=document.querySelector('#memberCropStatus');if(note)note.textContent='Photo framed and ready to save';
 avatarCropClose();toast('Profile picture framed');
}
function avatarCropOnPointer(e){const canvas=e.target.closest('#avatar-crop-canvas'),st=avatarCropState;if(!canvas||!st)return;
 const pos={x:e.clientX,y:e.clientY};if(e.type==='pointerdown'){e.preventDefault();canvas.setPointerCapture?.(e.pointerId);st.pointers.set(e.pointerId,pos);st.dragPoint=pos;
 if(st.pointers.size===2){const pts=Array.from(st.pointers.values());avatarCropPinch={distance:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y)||1,zoom:st.zoom};}return;}
 if(e.type==='pointermove'){if(!st.pointers.has(e.pointerId))return;e.preventDefault();st.pointers.set(e.pointerId,pos);
 if(st.pointers.size>=2&&avatarCropPinch){const pts=Array.from(st.pointers.values());const d=Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y)||1;
 st.zoom=avatarCropClamp(avatarCropPinch.zoom*d/avatarCropPinch.distance,1,3.5);const slider=document.getElementById('avatar-crop-zoom');if(slider)slider.value=String(st.zoom);
 }else if(st.dragPoint){const rect=canvas.getBoundingClientRect(),ratio=320/Math.max(1,rect.width);
 st.panX+=(pos.x-st.dragPoint.x)*ratio;st.panY+=(pos.y-st.dragPoint.y)*ratio;st.dragPoint=pos;}avatarCropDraw();return;}
 if(['pointerup','pointercancel','lostpointercapture'].includes(e.type)){st.pointers.delete(e.pointerId);st.dragPoint=st.pointers.size===1?Array.from(st.pointers.values())[0]:null;avatarCropPinch=null;}
}
avatarCropLayer.addEventListener('pointerdown',avatarCropOnPointer);
avatarCropLayer.addEventListener('pointermove',avatarCropOnPointer);
avatarCropLayer.addEventListener('pointerup',avatarCropOnPointer);
avatarCropLayer.addEventListener('pointercancel',avatarCropOnPointer);
avatarCropLayer.addEventListener('lostpointercapture',avatarCropOnPointer);
avatarCropLayer.addEventListener('input',e=>{if(e.target.id==='avatar-crop-zoom'&&avatarCropState){avatarCropState.zoom=+e.target.value;avatarCropDraw()}});
avatarCropLayer.addEventListener('click',e=>{const action=e.target.closest('[data-act]')?.dataset.act;
 try{if(action==='cancelAvatarCrop'){avatarCropClose();const file=document.querySelector('form[data-form="addMember"] [name="avatar"],form[data-form="editMember"] [name="avatar"]');if(file)file.value='';}
 if(action==='saveAvatarCrop')avatarCropSave();
 if(action==='rotateAvatarCrop'&&avatarCropState){avatarCropState.turn=(avatarCropState.turn+1)%4;avatarCropState.panX=avatarCropState.panY=0;avatarCropDraw()}
 if(action==='resetAvatarCrop'&&avatarCropState){Object.assign(avatarCropState,{zoom:1,panX:0,panY:0,turn:0});document.getElementById('avatar-crop-zoom').value='1';avatarCropDraw()}}
 catch(err){toast(err.message)}
});

function openModal(content){modal.hidden=false;modal.innerHTML=`<div class="modal-dialog" role="dialog" aria-modal="true"><div class="modal-title-row"><h2 class="modal-title">${content.title}</h2><button class="modal-close" type="button" data-act="closeModal" aria-label="Close">×</button></div>${content.body}</div>`}
function closeModal(){modal.hidden=true;modal.innerHTML=''}
function modalWallpaper(){const t=setWallpaper(),activePack=wallpaperPackKey();openModal({title:'Make gymclo yours',body:`<p class="section-desc">Wallpaper choices belong to your profile and sync across devices. They do not change anyone else's wallpaper.</p><label class="field">Curated themes</label><div class="theme-pack-grid">${Object.entries(THEME_PACKS).map(([id,p])=>`<button type="button" class="theme-pack ${activePack===id?'active':''}" data-act="themePack" data-value="${id}" data-pack="${id}"><b>${esc(p.label)}</b><span>${esc(p.desc)}</span><div class="theme-pack-preview"><i></i><i></i><i></i></div></button>`).join('')}</div><div class="label">Choose an atmosphere</div><div class="wall-presets">${['ember','oxide','slate','noir'].map(x=>`<button class="wall-option ${x} ${!t.photo&&t.theme===x?'active':''}" data-act="wallChoice" data-value="${x}" aria-label="${x} wallpaper"></button>`).join('')}</div><label class="field">Upload your own wallpaper</label><input class="input" id="wallInput" type="file" accept="image/*"><label class="field">Wallpaper darkness</label><input class="input" type="range" id="wallDim" min="0" max="0.7" step="0.05" value="${t.dim}"><label class="field">Text colour presets</label><div class="colour-presets">${[['default','Classic'],['rose','Rose'],['ice','Ice'],['mint','Mint'],['gold','Gold'],['lavender','Lavender'],['warm','Warm']].map(([id,label])=>`<button type="button" class="colour-swatch ${t.textColor===id?'active':''}" data-act="textTheme" data-value="${id}">${label}</button>`).join('')}</div><div class="button-row"><button class="btn ghost" data-act="wallReset">Restore default</button><button class="btn" data-act="closeModal">Done</button></div>`})}
function modalMember(id){croppedAvatarData='';const p=profile(id)||{},isCreate=!id;openModal({title:isCreate?'Add a crew member':'Edit profile',body:`<form data-form="${isCreate?'addMember':'editMember'}" data-id="${esc(id||'')}"><div style="display:flex;gap:14px;align-items:center"><span class="member-avatar-preview">${avatar(p,'lg')}</span><div class="grow"><label class="field" style="margin-top:0">Display name</label><input class="input" name="name" maxlength="28" value="${esc(p.name||'')}" required placeholder="Name"></div></div><label class="field">Profile picture</label><input class="input" type="file" name="avatar" accept="image/*"><div class="member-crop-help" id="memberCropStatus">Choose a photo to position it in a circular crop.</div>${p.avatar?`<button type="button" class="btn ghost small" data-act="reframeAvatar" data-id="${esc(id||'')}" style="margin-top:10px">Reframe existing photo</button>`:''}<div class="support-note" style="margin-top:8px">${isCreate?'After creating the member you will receive a private claim code to share with them. They choose their own four-digit PIN.':'The picture can be changed without affecting attendance or votes.'}</div><button class="btn full" style="margin-top:16px">${isCreate?'Add profile':'Save profile'}</button></form>${!isCreate&&p.id===me().id?`<button class="btn ghost full" style="margin-top:10px" data-act="logout">${I('logout',15)} Switch profile / sign out</button>`:''}`})}
function invitation(code){openModal({title:'Invitation created',body:`<p class="section-desc">Send this code privately to the member. It is shown only now; you can generate a new one in Admin.</p><div class="card soft" style="text-align:center;font-size:21px;font-weight:850;letter-spacing:.11em;overflow-wrap:anywhere" id="inviteCode">${esc(code)}</div><button class="btn full" data-act="copyInvite" data-value="${esc(code)}" style="margin-top:15px">Copy invitation code</button>`})}
function modalProposal(){const start=addDays(cycleStart(today()),28);openModal({title:'Pitch four fitness forfeits',body:`<p class="section-desc">Four progressively harder challenges for ${fmt(start)} – ${fmt(addDays(start,27))}. Members vote on the next cycle.</p><form data-form="proposal"><label class="field">Proposal name</label><input class="input" name="title" maxlength="64" required placeholder="The endurance ladder">${fallback.slice(0,4).map((f,i)=>`<label class="field">Week ${i+1} · ${i===0?'entry level':i===3?'hardest':'build up'}</label><input class="input" name="f${i}" maxlength="180" required value="${esc(f)}">`).join('')}<button class="btn full" style="margin-top:17px">Submit for group vote</button></form>`})}

async function showProof(id){const result=await api(`/api/checkins/${id}/proof`);openModal({title:'Workout evidence',body:result.proof?`<img src="${esc(result.proof)}" alt="Submitted workout evidence" style="width:100%;max-height:65vh;object-fit:contain;border-radius:14px">`:'<p class="muted">No preview photo for this demo entry.</p>'})}

let celebrationExitTimer=null;
function finishCelebration(){clearTimeout(celebrate.timer);clearTimeout(celebrationExitTimer);
 if(cel.hidden)return;
 tab='home';render();el.classList.add('home-arriving');cel.classList.add('celebration-leaving');
 celebrationExitTimer=setTimeout(()=>{cel.hidden=true;cel.classList.remove('celebration-leaving');cel.innerHTML='';el.classList.remove('home-arriving');window.scrollTo({top:0,behavior:'instant'});},640);
}
function celebrate(count,n,{extra=false}={}){
 clearTimeout(celebrate.timer);clearTimeout(celebrationExitTimer);cel.hidden=false;cel.classList.remove('celebration-leaving');
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const toastEl=document.getElementById('toast');if(toastEl)toastEl.classList.remove('visible');
 const safeTarget=Math.max(1,n||4),C=489,offset=C*(1-Math.min(1,count/safeTarget));
 const heading=extra?'Another session. Another win.':count>=safeTarget?'Four days. Complete.':'Session secured.';
 const supporting=extra?'Another workout recorded today. Your weekly day count stays the same.':count>=safeTarget?'Your weekly attendance target is complete.':'One more training day recorded. Keep the momentum.';
 cel.innerHTML=`<div class="celebrate-content" role="dialog" aria-modal="true" aria-label="Workout logged"><div class="celebrate-icon">${I('check',23)}</div><div class="celebrate-kicker">GYMCLO · TRAINING LOGGED</div><div class="celebrate-ring"><svg viewBox="0 0 200 200" aria-hidden="true"><circle class="track" cx="100" cy="100" r="78"/><circle class="active" cx="100" cy="100" r="78" style="--offset:${offset}"/></svg><div class="celebrate-count num"><span id="animateCount">${reduced?count:0}</span><span class="slash">/</span><span class="goal">${safeTarget}</span></div><span class="celebrate-ring-label">DAYS THIS WEEK</span></div><div class="celebrate-heading">${heading}</div><div class="celebrate-copy">${supporting}</div><div class="celebrate-foot"><span class="celebrate-small-dot"></span> RETURNING TO YOUR DASHBOARD <span class="celebrate-small-dot"></span></div><button type="button" class="btn ghost small" data-act="closeCelebration" style="margin-top:22px">Go to Home ${I('arrow',14)}</button></div>`;
 if(!reduced){for(let i=0;i<31;i++){const a=i/31*Math.PI*2,dist=100+Math.random()*180,particle=document.createElement('span');particle.className='particle';particle.style.setProperty('--dx',`${Math.cos(a)*dist}px`);particle.style.setProperty('--dy',`${Math.sin(a)*dist}px`);particle.style.setProperty('--r',`${Math.round(Math.random()*520)}deg`);particle.style.setProperty('--delay',`${Math.random()*.25}s`);cel.append(particle)}
 const counter=q('#animateCount'),start=performance.now();const anim=t=>{const p=Math.min(1,(t-start)/1030);if(counter?.isConnected)counter.textContent=Math.round(count*(1-Math.pow(1-p,3)));if(p<1&&counter?.isConnected&&!cel.hidden)requestAnimationFrame(anim)};requestAnimationFrame(anim);}
 celebrate.timer=setTimeout(finishCelebration,reduced?1300:3400);
}
async function act(a,btn){const value=btn.dataset.value,id=btn.dataset.id;switch(a){case'clearProof':formPhoto='';{const box=q('#proofPreview');if(box){box.classList.remove('has-image');box.innerHTML=''}const name=q('#proofUploadTitle');if(name)name.textContent='Attach workout evidence';const file=q('#checkinPhoto');if(file)file.value=''}break;case'textTheme':await saveWallpaper({textColor:value});modalWallpaper();toast('Text colour updated');break;case'themePack':{const p=THEME_PACKS[value];if(!p)break;await saveWallpaper({theme:p.theme,textColor:p.textColor,dim:p.dim,photo:''});modalWallpaper();toast(p.label+' applied');break}case'deleteChat':{const m=(S.messages||[]).find(x=>x.id===id);if(!m||m.profileId!==me()?.id)throw Error('You can only delete your own posts');const count=(S.messages||[]).filter(x=>x.parentId===id).length;if(!confirm(count?`Delete this post and its ${count} repl${count===1?'y':'ies'}? This cannot be undone.`:'Delete this post? This cannot be undone.'))break;await api(`/api/messages/${id}`,'DELETE');await refresh();toast('Post deleted');break}case'editChat':chatModal('',id);break;case'replyChat':chatModal(id);break;case'chatReact':await api(`/api/messages/${id}/react`,'POST',{emoji:value});await refresh();break;case'gifSelect':{const inp=q('#gifInput');if(inp)inp.value=`https://giphy.com/embed/${value}`;toast('GIF selected');break}case'gifSearch':{const search=q('#gifSearch')?.value?.trim();if(!search)throw Error('Enter a GIF search term');const result=await api('/api/giphy/search?q='+encodeURIComponent(search));const holder=q('#gifResults');if(holder)holder.innerHTML=result.gifs.map(g=>`<button type="button" data-act="gifSelect" data-value="${esc(g.id)}"><img src="${esc(g.url)}" alt="Choose GIF"></button>`).join('')||'<p class="micro">No GIFs found.</p>';break}case'radioToggle':{radioOpen=!radioOpen;updateRadioHistory();if(radioOpen&&!demoMode){try{const latest=await api('/api/jukebox?_='+Date.now());if(Array.isArray(latest.radioHistory)){S.radioHistory=latest.radioHistory;if(latest.jukebox)S.jukebox=latest.jukebox;updateRadioHistory()}}catch(err){toast('Could not refresh radio history: '+err.message)}}break}case'homeLogo':tab='home';window.scrollTo({top:0,behavior:'smooth'});render();break;case'nav':tab=value;window.scrollTo({top:0,behavior:'smooth'});render();break;case'wallpaper':modalWallpaper();break;case'vinylToggle':toggleVinyl();break;
case'radioSelect':{const result=await api('/api/radio-history/'+id+'/select','POST');S.jukebox=result.jukebox;S.radioHistory=result.radioHistory;render();toast('Track selected · tap the vinyl to play');break}
case'radioDelete':{if(!confirm('Remove your song from Radio history?'))break;const result=await api('/api/radio-history/'+id,'DELETE');S.jukebox=result.jukebox;S.radioHistory=result.radioHistory;render();toast('Song removed from Radio history');break}
case'deleteSession':if(!me()?.isAdmin)throw Error('Admin only');if(!confirm('Remove this approved workout? Only this session will be removed; the date still counts if other sessions remain.'))return;await api(`/api/admin/checkins/${id}/delete`,'POST');await refresh();toast('Approved workout removed');break;case'wallChoice':await saveWallpaper({theme:value,photo:''});qa('.wall-option').forEach(b=>b.classList.toggle('active',b.dataset.value===value));break;case'wallReset':await saveWallpaper({theme:'ember',photo:'',dim:.18});modalWallpaper();break;case'closeModal':closeModal();break;case'closeCelebration':finishCelebration();break;case'reframeAvatar':{const p=profile(id);if(p?.avatar)await avatarCropOpen(p.avatar);else toast('Choose a profile photo first');break}case'kind':selectedWorkout=value;qa('.kind-chip').forEach(b=>b.classList.toggle('active',b.dataset.value===value));break;case'admin':if(!me()?.isAdmin){toast('Admin only');break}if(!demoMode){let lock;try{lock=await api('/api/admin/status')}catch(err){throw Error('Server update required: upload the matching server.js to GitHub. '+err.message)}if(!lock.unlocked){openModal({title:'Unlock admin',body:'<p class="section-desc">Enter the admin PIN to edit forfeits and manage members.</p><form data-form="unlockAdmin"><label class="field">Four-digit admin PIN</label><input class="input" name="pin" inputmode="numeric" type="password" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" required><button class="btn full" style="margin-top:15px">Unlock control room</button></form>'});break}}tab='admin';render();break;case'cycle':forfeitView=value;render();break;case'profile':modalMember(me().id);break;case'chooseProfile':chooseProfile(id,btn.dataset.index);break;case'backToProfiles':pin={id:'',mode:'enter',buf:'',first:'',busy:false};renderEntry();break;case'pinDigit':await digit(value);break;case'logout':await api('/api/logout','POST');S=null;B=await api('/api/bootstrap');closeModal();renderEntry();break;case'cal':{let m=calendarMonth||activeMonth(),[y,mo]=m.split('-').map(Number);const d=new Date(Date.UTC(y,mo-1+Number(value),1));calendarMonth=`${d.getUTCFullYear()}-${n2(d.getUTCMonth()+1)}`;if(calendarMonth>activeMonth())calendarMonth=activeMonth();render();break}case'forfeitMonth':forfeitView=value;render();break;case'proof':await showProof(id);break;case'review':await api(`/api/checkins/${id}/review`,'POST',{status:value});await refresh();toast(`Submission ${value}`);break;case'markForfeit':await api('/api/forfeit-completed','POST',{profileId:id,week:value});await refresh();toast('Forfeit marked as completed');break;case'copyLink':await navigator.clipboard.writeText(location.origin);toast('Website link copied. Send each friend their separate invitation code.');break;case'copySummary':await navigator.clipboard.writeText(q('#summaryText').value);toast('Copied for WhatsApp');break;case'shareSummary':{const text=q('#summaryText').value;const shareUrl='https://wa.me/?text='+encodeURIComponent(text);window.open(shareUrl,'_blank','noopener');break}case'addMember':modalMember();break;case'editMember':modalMember(id);break;case'copyInvite':await navigator.clipboard.writeText(value);toast('Invitation code copied');break;case'resetPin':if(!confirm('Reset this member’s PIN? Their existing login sessions will be signed out.'))return;{const response=await api(`/api/profiles/${id}/reset`,'POST');await refresh();invitation(response.inviteCode);break}case'finalizeMvp':if(!confirm('Finalize the previous cycle’s votes and award the Diamond Crown to the unique winner?'))return;await api('/api/admin/mvp/finalize','POST',{start:value});await refresh();toast('Diamond Crown awarded to the voted MVP');break;case'propose':modalProposal();break;case'proposalVote':await api('/api/proposal-votes','POST',{proposalId:id});await refresh();toast('Your vote is recorded');break;case'applyProposal':if(!confirm('Apply these four forfeits to the next challenge cycle?'))return;await api('/api/apply-proposal','POST',{proposalId:id});await refresh();toast('Next cycle’s four forfeits updated');break;case'react':await api(`/api/feed/${id}/react`,'POST',{emoji:value});await refresh();break;case'shareSession':{const c=S.checkins.find(x=>x.id===id);if(!c||c.profileId!==me().id)throw Error('Not your session');await api(`/api/checkins/${id}/visibility`,'POST',{visible:!c.shareToFeed});await refresh();toast(c.shareToFeed?'Post made private':'Your post will appear once approved');break}case'mvp':if(!confirm('Cast your one MVP vote for this member?'))return;await api('/api/mvp-votes','POST',{start:value,candidateId:id});await refresh();toast('MVP vote submitted');break;case'reload':await boot();break}}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-act]');if(!btn||btn.disabled)return;try{await act(btn.dataset.act,btn)}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if(entry.hidden||!pin.id||pin.mode==='claim')return;if(/^\d$/.test(e.key)){e.preventDefault();digit(e.key)}else if(e.key==='Backspace'){e.preventDefault();digit('⌫')}else if(e.key==='Escape'){pin.id='';renderEntry()}});
entry.addEventListener('keydown',e=>{if(pin.id)return;const tiles=qa('.profile-tile');if(!tiles.length)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){selection=Math.max(0,Math.min(tiles.length-1,selection+(e.key==='ArrowRight'?1:-1)));qa('.profile-tile').forEach((t,i)=>t.classList.toggle('active',i===selection));tiles[selection].focus({preventScroll:true});e.preventDefault()}if(e.key==='Enter'&&e.target.closest('.profile-gallery')===null){tiles[selection]?.click()}});
entry.addEventListener('mouseover',e=>{const t=e.target.closest('.profile-tile');if(t){qa('.profile-tile').forEach(b=>b.classList.toggle('active',b===t))}});

// Show a name only while a touch pointer is held on a profile (350 ms).
let bubbleHoldTimer=null,bubbleHeld=null;
entry.addEventListener('pointerdown',e=>{
 if(e.pointerType==='mouse')return;
 const tile=e.target.closest('.profile-tile');if(!tile)return;
 clearTimeout(bubbleHoldTimer);bubbleHeld=tile;
 bubbleHoldTimer=setTimeout(()=>{if(bubbleHeld===tile){tile.classList.add('holding');tile.dataset.longHeld='true'}},350);
});
function clearBubbleHold(){clearTimeout(bubbleHoldTimer);bubbleHeld?.classList.remove('holding');bubbleHeld=null}
entry.addEventListener('click',e=>{const tile=e.target.closest('.roulette-profile');if(tile?.dataset.longHeld==='true'){e.preventDefault();e.stopPropagation();delete tile.dataset.longHeld;}},true);
entry.addEventListener('pointerup',clearBubbleHold);
entry.addEventListener('pointercancel',e=>{e.target.closest('.roulette-profile')?.removeAttribute('data-long-held');clearBubbleHold()});
entry.addEventListener('pointerleave',clearBubbleHold);

// Bubble lens follows the pointer gently without changing selection/login flow.
entry.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||!window.matchMedia('(prefers-reduced-motion: no-preference)').matches)return;const tile=e.target.closest('.profile-tile');if(!tile)return;const bubble=tile.querySelector('.avatar');if(!bubble)return;const r=bubble.getBoundingClientRect();const x=Math.max(-1,Math.min(1,(e.clientX-r.left-r.width/2)/(r.width/2)));const y=Math.max(-1,Math.min(1,(e.clientY-r.top-r.height/2)/(r.height/2)));bubble.style.setProperty('--bx',`${(-y*8).toFixed(2)}deg`);bubble.style.setProperty('--by',`${(x*8).toFixed(2)}deg`);bubble.style.setProperty('--ix',`${(-x*3).toFixed(1)}px`);bubble.style.setProperty('--iy',`${(-y*3).toFixed(1)}px`)});
entry.addEventListener('pointerout',e=>{const tile=e.target.closest('.profile-tile');if(!tile||tile.contains(e.relatedTarget))return;const bubble=tile.querySelector('.avatar');if(!bubble)return;for(const v of ['--bx','--by','--ix','--iy'])bubble.style.removeProperty(v)});

modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='wallDim')document.documentElement.style.setProperty('--shade',+e.target.value)});
document.addEventListener('change',async e=>{if(e.target.matches('form[data-form="addMember"] [name="avatar"],form[data-form="editMember"] [name="avatar"]')&&e.target.files?.[0]){try{await avatarCropOpen(e.target.files[0])}catch(err){toast(err.message)}return}if(e.target.id==='radioFilter'){radioFilter=e.target.value;updateRadioHistory()}if(e.target.id==='wallInput'&&e.target.files[0]){try{const photo=await imageFile(e.target.files[0],1100,.7);await saveWallpaper({photo});toast('Wallpaper saved to your profile')}catch(err){toast(err.message)}}if(e.target.id==='checkinPhoto'&&e.target.files[0]){try{formPhoto=await imageFile(e.target.files[0],750,.62);const label=q('#proofUploadTitle');if(label)label.textContent='Evidence ready';const preview=q('#proofPreview');if(preview){preview.classList.add('has-image');preview.innerHTML=`<img alt="Selected workout evidence" src="${formPhoto}"><span class="grow micro">Photo attached · ready to submit</span><button type="button" class="proof-remove" data-act="clearProof">Remove</button>`}toast('Evidence ready to submit')}catch(err){formPhoto='';toast(err.message)}}if(e.target.id==='wallDim'){try{await saveWallpaper({dim:+e.target.value});toast('Wallpaper darkness saved')}catch(err){toast(err.message)}}if(e.target.dataset.archive==='calendar'){calendarMonth=e.target.value;render()}if(e.target.dataset.archive==='adminCycle'){adminCycle=e.target.value;render()}if(e.target.dataset.archive==='approvedMonth'){approvedMonth=e.target.value;render()}if(e.target.name==='month'&&e.target.closest('[data-form="rules"]')){adminMonth=e.target.value;render()}});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(loading)return;loading=true;const submit=q('button[type=submit]',form);if(submit)submit.disabled=true;const b=Object.fromEntries(new FormData(form));try{switch(form.dataset.form){case'chatPost':case'chatEdit':{const file=form.querySelector('[name=image]')?.files?.[0],photo=file?await imageFile(file,850,.67):undefined;const isEdit=form.dataset.form==='chatEdit',body={text:b.text||'',gifUrl:b.gifUrl||''};if(isEdit){if(photo!==undefined)body.image=photo;else if(b.removeImage==='on')body.image='';await api('/api/messages/'+form.dataset.id,'PATCH',body)}else{body.parentId=form.dataset.parent||null;body.image=photo||'';await api('/api/messages','POST',body)}closeModal();await refresh();toast(isEdit?'Message updated':'Message posted');break}case'jukebox':{if(!validSoundcloudUrl(b.url))throw Error('Paste a public soundcloud.com track or playlist link');let trackTitle='';try{const info=await fetch('https://soundcloud.com/oembed?format=json&url='+encodeURIComponent(b.url)).then(r=>r.ok?r.json():null);trackTitle=String(info?.title||'').slice(0,120)}catch{/* A valid SoundCloud widget URL can still be saved if oEmbed is unavailable */}const saved=await api('/api/jukebox','POST',{url:b.url,title:trackTitle});S.jukebox=saved.jukebox;S.radioHistory=saved.radioHistory||S.radioHistory;render();toast('Crew soundtrack updated. Tap the vinyl to play.');break}case'setup':await api('/api/setup','POST',{name:b.name,setupCode:b.setupCode,pin:b.pin});await boot();break;case'claimCode':pin.claimCode=b.code.trim().toUpperCase();pin.mode='create';pin.buf='';renderPin();break;case'checkin':if(!formPhoto)throw Error('Choose a proof photo before submitting');await api('/api/checkins','POST',{kind:selectedWorkout,note:b.workoutNote||q('#workoutNote')?.value||'',proof:formPhoto,shareToFeed:b.shareToFeed==='on'});formPhoto='';{const hadToday=todayLogged();await refresh();const count=weekCount(me().id,activeWeek());celebrate(count,cycleRule(activeWeek()).target,{extra:hadToday});}break;case'addMember':{const avatar=croppedAvatarData||'';const result=await api('/api/profiles','POST',{name:b.name,avatar});await refresh();invitation(result.inviteCode);break}case'editMember':{const p=profile(form.dataset.id);await api(`/api/profiles/${form.dataset.id}`,'PATCH',{name:b.name,avatar:croppedAvatarData||p.avatar});await refresh();closeModal();toast('Profile updated');break}case'unlockAdmin':await api('/api/admin/unlock','POST',{pin:b.pin});closeModal();tab='admin';render();toast('Admin unlocked for 15 minutes');break;case'adminCheckin':await api('/api/admin/checkins','POST',{profileId:b.profileId,day:b.day,kind:b.kind,note:b.note||''});await refresh();toast('Missed session added to attendance');break;case'setMvpCrown':{if(!confirm('Award the Diamond Crown to this member? The previous MVP will lose the crown.'))break;await api('/api/admin/mvp/crown','POST',{profileId:b.profileId});await refresh();toast('Diamond Crown awarded');break;}case'cycleRules':await api('/api/cycle-rules','POST',{start:b.start,target:+b.target,forfeits:Array.from({length:4},(_,i)=>b['f'+i])});await refresh();toast('Four-week forfeits updated');break;case'rules':await api('/api/rules','POST',{month:b.month,target:+b.target,forfeits:Array.from({length:5},(_,i)=>b['f'+i])});await refresh();toast('Monthly rules saved');break;case'proposal':await api('/api/proposals','POST',{start:addDays(cycleStart(today()),28),title:b.title,forfeits:Array.from({length:4},(_,i)=>b['f'+i])});await refresh();closeModal();toast('Four-week proposal published for voting');break}}catch(err){toast(err.message)}finally{loading=false;if(submit?.isConnected)submit.disabled=false}});
async function checkPendingBadge(){
 if(!S?.me?.isAdmin||demoMode||document.hidden)return;
 try{const result=await api('/api/admin/pending-count');if(typeof result.count!=='number')return;
 if(pendingNotifyCount!==result.count){pendingNotifyCount=result.count;
 const current=q('.admin-alert-count');if(current){current.remove()}
 const button=q('.top-admin');if(button&&result.count){const mark=document.createElement('span');mark.className='admin-alert-count';mark.textContent=result.count>99?'99+':String(result.count);mark.title=`${result.count} photo approvals waiting`;mark.setAttribute('aria-label',mark.title);button.append(mark)}
 }
 }catch{/* The badge will refresh on next navigation; do not interrupt the user. */}
}
setInterval(checkPendingBadge,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkPendingBadge()});
boot();

